import type { BankQuestion } from "@/lib/bank";

/** Constitutional and Statutory Bodies (Indian Polity): 222 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id": "polity-constitutional-bodies-1", "question": "The Election Commission of India is provided for in:", "options": ["Article 280", "Article 315", "Article 324", "Article 148"], "answer": 2, "explanation": "Article 324 vests the superintendence, direction and control of elections in the Election Commission. Article 280 is the Finance Commission and Article 315 is the UPSC.", "difficulty": "easy", "source": "SSC CGL · RRB NTPC · State PSCs"},
  {"id": "polity-constitutional-bodies-2", "question": "The Comptroller and Auditor General of India is provided for in:", "options": ["Article 324", "Article 76", "Article 280", "Article 148"], "answer": 3, "explanation": "Article 148 provides for the CAG, appointed by the President. Article 76 is the Attorney General.", "difficulty": "easy", "source": "SSC CGL · RRB NTPC · State PSCs"},
  {"id": "polity-constitutional-bodies-3", "question": "The Union Public Service Commission is provided for in:", "options": ["Article 315", "Article 320", "Article 338", "Article 312"], "answer": 0, "explanation": "Article 315 provides for Public Service Commissions for the Union and the States. Article 320 lists their functions, and Article 312 deals with All-India Services.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL"},
  {"id": "polity-constitutional-bodies-4", "question": "The Finance Commission is set up under:", "options": ["Article 266", "Article 263", "Article 360", "Article 280"], "answer": 3, "explanation": "Article 280 requires the President to set up a Finance Commission. Article 360 is Financial Emergency, and Article 263 is the Inter-State Council.", "difficulty": "easy", "source": "SSC CGL · RRB NTPC · State PSCs"},
  {"id": "polity-constitutional-bodies-5", "question": "Who is the highest law officer of the Government of India?", "options": ["Union Law Minister", "Chief Justice of India", "Attorney General", "Solicitor General"], "answer": 2, "explanation": "The Attorney General (Article 76) is the Government of India's highest law officer. The Solicitor General is the second law officer, and that post is created by statute, not the Constitution.", "difficulty": "moderate", "source": "SSC CGL · RRB NTPC · State PSCs"},
  {"id": "polity-constitutional-bodies-6", "question": "NITI Aayog, which replaced the Planning Commission, came into being on:", "options": ["1 April 2015", "15 August 2014", "1 January 2015", "26 January 2015"], "answer": 2, "explanation": "NITI Aayog was set up on 1 January 2015 by a Union Cabinet resolution. Like the Planning Commission, it is neither constitutional nor statutory.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "polity-constitutional-bodies-7", "question": "The National Human Rights Commission was set up under:", "options": ["Article 338", "The Protection of Human Rights Act, 1993", "The Human Rights Act, 1998", "A Presidential order of 1990"], "answer": 1, "explanation": "The NHRC is a statutory body set up in October 1993 under the Protection of Human Rights Act, 1993. It is not a constitutional body.", "difficulty": "moderate", "source": "SSC CGL · RRB NTPC · State PSCs"},
  {"id": "polity-constitutional-bodies-8", "question": "The Central Information Commission was set up under:", "options": ["Article 19(1)(a)", "The Official Secrets Act, 1923", "The Right to Information Act, 2005", "The Lokpal Act, 2013"], "answer": 2, "explanation": "The Central Information Commission is a statutory body created by the RTI Act, 2005. It hears appeals and complaints against central public authorities.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "polity-constitutional-bodies-9", "question": "Who was the first Chairperson of the Lokpal of India?", "options": ["Justice A. M. Khanwilkar", "Justice J. S. Khehar", "Justice Ranjan Gogoi", "Justice Pinaki Chandra Ghose"], "answer": 3, "explanation": "Justice Pinaki Chandra Ghose became the first Lokpal in March 2019 under the Lokpal and Lokayuktas Act, 2013. Justice A. M. Khanwilkar took over in 2024.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "polity-constitutional-bodies-10", "question": "The Comptroller and Auditor General can be removed from office:", "options": ["By the Public Accounts Committee", "By a simple majority resolution of the Lok Sabha", "By the President at pleasure", "In the same way and on the same grounds as a Supreme Court judge"], "answer": 3, "explanation": "Article 148(1) says the CAG can be removed only like a Supreme Court judge: for proved misbehaviour or incapacity, by special majority addresses of both Houses. This protects the CAG's independence.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · State PSCs"},
  {"id": "polity-constitutional-bodies-11", "question": "The CAG's reports on the accounts of the Union are submitted to the:", "options": ["President, who has them laid before Parliament", "Speaker of the Lok Sabha", "Prime Minister", "Union Finance Minister"], "answer": 0, "explanation": "Under Article 151 Union audit reports go to the President, who has them laid before each House. State reports go to the Governor.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · UPSC Prelims"},
  {"id": "polity-constitutional-bodies-12", "question": "A separate National Commission for Scheduled Tribes (Article 338A) was created by the:", "options": ["65th Amendment", "102nd Amendment", "89th Amendment", "73rd Amendment"], "answer": 2, "explanation": "The 89th Amendment (2003) split the old combined commission into the NCSC (Article 338) and the NCST (Article 338A). The 102nd Amendment (2018) gave constitutional status to the Backward Classes Commission (Article 338B).", "difficulty": "moderate", "source": "UPSC Prelims · State PSCs"},
  {"id": "polity-constitutional-bodies-13", "question": "How can an Election Commissioner, other than the Chief Election Commissioner, be removed?", "options": ["By the President at pleasure", "Only on the recommendation of the Chief Election Commissioner", "In the same way as a Supreme Court judge", "By a resolution of the Rajya Sabha"], "answer": 1, "explanation": "Article 324(5) protects the CEC in the same way as a Supreme Court judge. The other Election Commissioners cannot be removed except on the CEC's recommendation.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "polity-constitutional-bodies-14", "question": "Members of a State Public Service Commission retire at the age of:", "options": ["60 years", "70 years", "65 years", "62 years"], "answer": 3, "explanation": "Under Article 316(2), State PSC members serve six years or until 62, whichever comes first. UPSC members serve until 65.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL · State PSCs"},
  {"id": "polity-constitutional-bodies-15", "question": "To remove a UPSC member for misbehaviour, the President must first:", "options": ["Get a two-thirds resolution of Parliament", "Get the Prime Minister's written advice", "Refer the matter to the Supreme Court for an inquiry", "Consult the Chief Election Commissioner"], "answer": 2, "explanation": "Under Article 317(1), removal for misbehaviour needs a Supreme Court inquiry first. The Court's report binds the President. Grounds such as insolvency need no reference.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "polity-constitutional-bodies-16", "question": "A member of a State Public Service Commission is appointed by the Governor but can be removed only by the:", "options": ["Governor", "Chief Minister", "High Court", "President"], "answer": 3, "explanation": "Article 317 gives the power of removal to the President alone, even for State PSC members. The Governor can only suspend a member while a Supreme Court reference is pending.", "difficulty": "hard", "source": "UPSC Prelims · State PSCs"},
  {"id": "polity-constitutional-bodies-17", "question": "Which of these can the Attorney General NOT do?", "options": ["Speak in either House of Parliament", "Appear in any court in India", "Vote in a joint sitting of Parliament", "Be a member of a parliamentary committee"], "answer": 2, "explanation": "Article 88 lets the Attorney General speak in either House, in a joint sitting and in committees, but without the right to vote. Article 76(3) gives a right of audience in all courts in India.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL · UPSC Prelims"},
  {"id": "polity-constitutional-bodies-18", "question": "The CAG holds office for:", "options": ["During the pleasure of the President", "Five years or until 62", "Six years or until 65, whichever is earlier", "Until the age of 70"], "answer": 2, "explanation": "The CAG's (Duties, Powers and Conditions of Service) Act, 1971 sets a six-year term or the age of 65, whichever comes first.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "polity-constitutional-bodies-19", "question": "The Finance Commission consists of:", "options": ["A chairman and six other members", "Five members including the Finance Minister", "A chairman and four other members", "A chairman and two other members"], "answer": 2, "explanation": "Under Article 280 and the Finance Commission (Miscellaneous Provisions) Act, 1951, it has a chairman and four other members, appointed by the President.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL · State PSCs"},
  {"id": "polity-constitutional-bodies-20", "question": "Who chairs the Sixteenth Finance Commission, which covers the period from 2026–27?", "options": ["Y. V. Reddy", "Vijay Kelkar", "N. K. Singh", "Arvind Panagariya"], "answer": 3, "explanation": "The Sixteenth Finance Commission, set up on 31 December 2023, is chaired by Arvind Panagariya. N. K. Singh chaired the Fifteenth Commission.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL · UPSC Prelims"},
  {"id": "polity-constitutional-bodies-21", "question": "Which of these is NOT a constitutional post?", "options": ["Solicitor General of India", "Advocate General of a State", "Attorney General for India", "Comptroller and Auditor General"], "answer": 0, "explanation": "The Attorney General (Article 76), the Advocate General (Article 165) and the CAG (Article 148) are constitutional. The Solicitor General's post comes from the Law Officers (Conditions of Service) Rules.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "polity-constitutional-bodies-22", "question": "The NHRC Chairperson is appointed by the President on the recommendation of a committee headed by the:", "options": ["Speaker of the Lok Sabha", "Chief Justice of India", "Prime Minister", "Union Home Minister"], "answer": 2, "explanation": "The committee is chaired by the Prime Minister. Its other members are the Lok Sabha Speaker, the Rajya Sabha Deputy Chairman, the Leaders of Opposition in both Houses and the Union Home Minister.", "difficulty": "hard", "source": "UPSC Prelims · State PSCs"},
  {"id": "polity-constitutional-bodies-23", "question": "The Chief Information Commissioner is appointed by the President on the recommendation of a committee of the:", "options": ["President, Vice-President and PM", "PM, Home Minister and Law Minister", "PM, Leader of Opposition in the Lok Sabha and a Union Cabinet Minister nominated by the PM", "PM, CJI and Speaker"], "answer": 2, "explanation": "Section 12(3) of the RTI Act, 2005 sets this committee: the Prime Minister, the Leader of Opposition in the Lok Sabha (or leader of the largest opposition group), and a Cabinet Minister the Prime Minister nominates.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "polity-constitutional-bodies-24", "question": "Which of these is NOT a member of the Lokpal selection committee?", "options": ["Chairman of the Rajya Sabha", "Prime Minister", "Speaker of the Lok Sabha", "Chief Justice of India or a judge nominated by them"], "answer": 0, "explanation": "The committee is the Prime Minister, the Lok Sabha Speaker, the Leader of Opposition in the Lok Sabha, the CJI or a nominated judge, and an eminent jurist. The Rajya Sabha Chairman is not on it.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "polity-constitutional-bodies-25", "question": "How many of these statements about the Election Commission are correct? I. It became multi-member for a short time in 1989–90 and permanently from 1993. II. The Constitution does not set qualifications for Election Commissioners. III. The Constitution does not bar retired Election Commissioners from later government posts. IV. The Constitution fixes their term at six years.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct. The term is not in the Constitution; it comes from statute, now the 2023 Act, as six years or until age 65.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-constitutional-bodies-26", "question": "Under the Chief Election Commissioner and Other Election Commissioners Act, 2023, the selection committee consists of:", "options": ["The PM, the CJI and the Leader of Opposition in the Lok Sabha", "The President, the PM and the CJI", "The PM, the Leader of Opposition in the Lok Sabha and a Union Cabinet Minister nominated by the PM", "The PM, the Speaker and the Chairman of the Rajya Sabha"], "answer": 2, "explanation": "The 2023 Act replaced the interim committee set by the Supreme Court in Anoop Baranwal (March 2023), which included the CJI. The CJI is not on the statutory committee.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-constitutional-bodies-27", "question": "How many of these statements about the CAG are correct? I. The CAG is often called the guardian of the public purse. II. The CAG audits the receipts and spending of both the Union and the States. III. In India the CAG has no control over the release of money from the Consolidated Fund. IV. After leaving office, the CAG can take another post under the Government of India.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct. The Indian CAG is only an auditor, not a comptroller of withdrawals. Article 148(4) bars the CAG from any further office under the Union or a State.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-constitutional-bodies-28", "question": "How many of these statements about the Attorney General for India are correct? I. The AG is appointed by the President and holds office during the President's pleasure. II. The Constitution fixes the AG's term at five years. III. The AG has the privileges of a Member of Parliament. IV. The AG must be qualified to be appointed a Supreme Court judge.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I (Article 76(4)), III (Article 105(4)) and IV (Article 76(1)) are correct. The Constitution sets no term for the AG.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-constitutional-bodies-29", "question": "Assertion (A): The President cannot remove the CAG at pleasure. Reason (R): The CAG can be removed only in the manner and on the grounds that apply to a Supreme Court judge.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Both are true, and R explains A. Article 148(1) ties the CAG's removal to the Article 124(4) procedure, which takes it out of the President's pleasure.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-constitutional-bodies-30", "question": "Which pair of body and Article is NOT correctly matched?", "options": ["Finance Commission — Article 280", "Election Commission — Article 324", "Attorney General for India — Article 165", "National Commission for Backward Classes — Article 338B"], "answer": 2, "explanation": "The Attorney General is under Article 76. Article 165 is the Advocate General of a State. The other three pairs are correct.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSCs"},
  {"id": "polity-constitutional-bodies-31", "question": "How many of these are constitutional bodies? I. GST Council II. National Human Rights Commission III. Central Vigilance Commission IV. NITI Aayog", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 0, "explanation": "Only the GST Council (Article 279A, 101st Amendment) is constitutional. The NHRC (1993 Act) and the CVC (2003 Act) are statutory, and NITI Aayog was set up by executive resolution.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-constitutional-bodies-32", "question": "How many of these statements about the Finance Commission are correct? I. It is set up every fifth year or earlier. II. It recommends how the net proceeds of taxes are shared between the Union and the States. III. Its recommendations are binding on the Union Government.", "options": ["Only one", "Only two", "All three", "None"], "answer": 1, "explanation": "I and II are correct under Article 280. Its recommendations are advisory; the Government decides whether to accept them.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-constitutional-bodies-33", "question": "How many of these statements about the UPSC are correct? I. It must be consulted on reserving posts for backward classes. II. Its Chairman cannot take any further job under the Government of India or a State. III. A UPSC member can be appointed Chairman of the UPSC or of a State PSC. IV. Its advice binds the Government.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "II and III are correct (Article 319). Article 320(4) says the UPSC need not be consulted on reservations under Article 16(4). Its advice is not binding.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-constitutional-bodies-34", "question": "How many of these statements about NITI Aayog are correct? I. It was set up by an executive resolution of the Union Cabinet. II. The Prime Minister is its ex officio Chairperson. III. Its Governing Council includes the Chief Ministers of all States and of Union Territories with legislatures. IV. Its Vice-Chairperson is appointed by the Prime Minister.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct. NITI Aayog does not allocate funds to States, which is a key difference from the old Planning Commission.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-constitutional-bodies-35", "question": "Arrange in time order: 1. NITI Aayog set up 2. NHRC set up 3. Lokpal and Lokayuktas Act passed 4. Central Information Commission set up", "options": ["2, 3, 4, 1", "2, 4, 3, 1", "2, 4, 1, 3", "4, 2, 3, 1"], "answer": 1, "explanation": "NHRC (1993), CIC (2005), Lokpal and Lokayuktas Act (2013), NITI Aayog (January 2015).", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-constitutional-bodies-36", "question": "How many of these statements about the Central Information Commission are correct? I. Since the 2019 amendment to the RTI Act, the term and salaries of Information Commissioners are set by the Central Government. II. It is a constitutional body. III. It can fine a Public Information Officer up to ₹25,000. IV. It hears appeals against State Government departments.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "I and III are correct. The penalty is ₹250 a day, up to ₹25,000. The CIC is statutory, and appeals about State public authorities go to the State Information Commission.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-constitutional-bodies-37", "question": "How many of these statements about the NHRC are correct? I. Its Chairperson can be a former Chief Justice of India or a former Supreme Court judge. II. It cannot inquire into a matter more than one year after the act complained of. III. Its recommendations bind the government. IV. The chairpersons of the national commissions for SCs, STs, women and minorities are deemed members.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I (after the 2019 amendment), II (Section 36(2)) and IV are correct. The NHRC's recommendations are advisory, not binding.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-constitutional-bodies-38", "question": "How many of these statements about the Lokpal are correct? I. It has a Chairperson and up to eight members, half of whom are judicial members. II. At least half its members must be from SCs, STs, OBCs, minorities or women. III. The Prime Minister is within its jurisdiction, with certain subjects excluded. IV. The Act required States to set up Lokayuktas within one year of its commencement.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct under the Lokpal and Lokayuktas Act, 2013. Matters of international relations, security, public order, atomic energy and space are excluded for the Prime Minister. Section 63 required Lokayuktas within a year.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-constitutional-bodies-39", "question": "Assertion (A): The Election Commission of India conducts elections to Parliament, the State legislatures, and the offices of President and Vice-President. Reason (R): The Election Commission of India also conducts elections to panchayats and municipalities.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 2, "explanation": "A is true under Article 324. R is false: local body elections are run by State Election Commissions under Articles 243K and 243ZA.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-constitutional-bodies-40", "question": "Which pair of Finance Commission and Chairman is NOT correctly matched?", "options": ["Fourteenth — N. K. Singh", "Sixteenth — Arvind Panagariya", "Thirteenth — Vijay Kelkar", "First — K. C. Neogy"], "answer": 0, "explanation": "The Fourteenth Finance Commission was chaired by Y. V. Reddy. N. K. Singh chaired the Fifteenth, which recommended a 41% share of the divisible pool for the States.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "polity-constitutional-bodies-41", "question": "The National Commission for Scheduled Castes is provided for in:", "options": ["Article 330", "Article 335", "Article 338", "Article 340"], "answer": 2, "explanation": "Article 338 provides the National Commission for Scheduled Castes. Article 338A is the Commission for STs and Article 340 the commission to investigate the conditions of backward classes.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL"},
  {"id": "polity-constitutional-bodies-42", "question": "The Chief Election Commissioner of India is appointed by the:", "options": ["Prime Minister", "Chief Justice of India", "President", "Parliament"], "answer": 2, "explanation": "Under Article 324(2) the President appoints the CEC and other Election Commissioners, now on the recommendation of the selection committee set up by the 2023 Act.", "difficulty": "easy", "source": "RRB NTPC · SSC CGL"},
  {"id": "polity-constitutional-bodies-43", "question": "By law, the salary of the Comptroller and Auditor General of India is equal to that of a:", "options": ["Union Cabinet minister", "Judge of the Supreme Court", "Judge of a High Court", "Cabinet Secretary"], "answer": 1, "explanation": "The CAG's salary and service conditions are set by Parliament (the CAG (Duties, Powers and Conditions of Service) Act, 1971) and equal those of a Supreme Court judge.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL"},
  {"id": "polity-constitutional-bodies-44", "question": "The National Commission for Women was set up in:", "options": ["1990", "1992", "1993", "1995"], "answer": 1, "explanation": "The Commission was constituted on 31 January 1992 under the National Commission for Women Act, 1990; the Act's year is the usual trap.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL"},
  {"id": "polity-constitutional-bodies-45", "question": "A member of the Union Public Service Commission holds office for six years or until the age of:", "options": ["60 years", "62 years", "65 years", "70 years"], "answer": 2, "explanation": "Under Article 316(2), a UPSC member serves six years or until 65, whichever is earlier. For State PSC members the age limit is 62.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL"},
  {"id": "polity-constitutional-bodies-46", "question": "The Special Officer for Linguistic Minorities is provided for in:", "options": ["Article 29", "Article 347", "Article 350A", "Article 350B"], "answer": 3, "explanation": "Article 350B, added by the 7th Amendment (1956), provides this officer, appointed by the President. Article 350A is about instruction in the mother tongue at the primary stage.", "difficulty": "moderate", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-constitutional-bodies-47", "question": "The National Commission for Backward Classes became a constitutional body through the:", "options": ["93rd Amendment", "101st Amendment", "102nd Amendment", "103rd Amendment"], "answer": 2, "explanation": "The 102nd Amendment (2018) inserted Article 338B. The 103rd Amendment brought EWS reservation and the 101st brought GST.", "difficulty": "moderate", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-constitutional-bodies-48", "question": "The functions of the Public Service Commissions, including the matters on which they must be consulted, are set out in:", "options": ["Article 315", "Article 316", "Article 320", "Article 323"], "answer": 2, "explanation": "Article 320 lists their functions. Article 315 creates the commissions, 316 covers appointment and term, and 323 their reports.", "difficulty": "moderate", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-constitutional-bodies-49", "question": "The Advocate General of a State is appointed by the Governor and must be qualified to be appointed a:", "options": ["Judge of the Supreme Court", "Judge of a High Court", "District judge", "Member of the Legislative Assembly"], "answer": 1, "explanation": "Article 165(1) requires the Advocate General to be qualified to be a High Court judge. The Attorney General must be qualified to be a Supreme Court judge.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "polity-constitutional-bodies-50", "question": "The office of the Solicitor General of India is:", "options": ["Created by Article 76", "Created by Article 165", "Not mentioned in the Constitution", "Created by Article 88"], "answer": 2, "explanation": "The Constitution provides only for the Attorney General (Article 76). The Solicitor General and Additional Solicitors General are appointed under the Law Officers (Conditions of Service) Rules, 1987.", "difficulty": "moderate", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-constitutional-bodies-51", "question": "Who was the first Chairperson of the National Commission for Women?", "options": ["Mohini Giri", "Jayanti Patnaik", "Girija Vyas", "Rekha Sharma"], "answer": 1, "explanation": "Jayanti Patnaik headed the first Commission in 1992. Mohini Giri and Girija Vyas came later.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "polity-constitutional-bodies-52", "question": "Both the Central Bureau of Investigation (1963) and the Central Vigilance Commission (1964) owe their origin to the recommendations of the:", "options": ["Kothari Committee", "Santhanam Committee", "Shah Commission", "Administrative Reforms Commission (1966)"], "answer": 1, "explanation": "The Santhanam Committee on Prevention of Corruption (1962–64) recommended the CVC; the CBI was set up by a Home Ministry resolution in 1963 in the same context.", "difficulty": "moderate", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-constitutional-bodies-53", "question": "The National Commission for Protection of Child Rights was set up under an Act passed in:", "options": ["1992", "2000", "2005", "2012"], "answer": 2, "explanation": "The Commissions for Protection of Child Rights Act, 2005 provides for the NCPCR (set up in 2007) and State commissions. The POCSO Act came in 2012.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "polity-constitutional-bodies-54", "question": "The term ‘Lokpal’ was coined in 1963 by:", "options": ["Anna Hazare", "L. M. Singhvi", "Morarji Desai", "K. Santhanam"], "answer": 1, "explanation": "L. M. Singhvi coined the term in a Lok Sabha debate. Morarji Desai headed the Administrative Reforms Commission (1966) that recommended a Lokpal and Lokayuktas.", "difficulty": "moderate", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-constitutional-bodies-55", "question": "The 105th Amendment (2021):", "options": ["Gave constitutional status to the NCBC", "Restored the power of States to prepare their own lists of socially and educationally backward classes", "Introduced EWS reservation", "Extended SC/ST reservation in legislatures for ten years"], "answer": 1, "explanation": "After the Maratha reservation judgment (2021) read the 102nd Amendment as taking this power away, the 105th Amendment restored it. The NCBC got constitutional status in the 102nd.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-constitutional-bodies-56", "question": "The qualifications of the members of the Finance Commission are determined by:", "options": ["The Constitution itself, in Article 280", "Parliament, by law", "The President, by order", "The Union Cabinet"], "answer": 1, "explanation": "Article 280(2) leaves qualifications to Parliament, which passed the Finance Commission (Miscellaneous Provisions) Act, 1951. The President only appoints the members.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-constitutional-bodies-57", "question": "In the case of the UPSC, the number of members and their conditions of service are fixed by:", "options": ["Parliament, by law", "The UPSC itself", "Regulations made by the President", "The Department of Personnel, by notification"], "answer": 2, "explanation": "Article 318 lets the President make regulations for the UPSC (and the Governor for a State PSC) on the number of members and their service conditions.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-constitutional-bodies-58", "question": "Under Article 324(5), the conditions of service and tenure of office of the Election Commissioners are:", "options": ["Fixed in the Second Schedule", "Determined by the Chief Election Commissioner", "Determined by the President by rule, subject to any law made by Parliament", "Fixed by the Union Cabinet"], "answer": 2, "explanation": "Article 324(5) gives the President rule-making power subject to parliamentary law; Parliament has since legislated (most recently the 2023 Act).", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-constitutional-bodies-59", "question": "The Delimitation Commission set up in 2002 was headed by:", "options": ["Justice J. L. Kapur", "Justice Kuldip Singh", "Justice Ranjana Prakash Desai", "Justice N. Chandrasekhara Aiyar"], "answer": 1, "explanation": "Justice Kuldip Singh chaired the 2002 commission, which redrew constituencies on the 2001 Census. Ranjana Prakash Desai headed the Jammu and Kashmir delimitation (2020–22).", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-constitutional-bodies-60", "question": "The freeze on the total number of Lok Sabha seats allotted to States, based on the 1971 Census, was extended until the first Census after 2026 by the:", "options": ["42nd Amendment", "61st Amendment", "84th Amendment", "91st Amendment"], "answer": 2, "explanation": "The 42nd Amendment (1976) first froze seats till 2000; the 84th Amendment (2001) extended the freeze till the first Census taken after 2026.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-constitutional-bodies-61", "question": "The Central Vigilance Commissioner is appointed by the President on the recommendation of a committee of the:", "options": ["Prime Minister, Chief Justice of India and Leader of the Opposition", "Prime Minister, Union Home Minister and Leader of the Opposition in the Lok Sabha", "Prime Minister, Speaker and Union Law Minister", "President, Prime Minister and Chief Justice of India"], "answer": 1, "explanation": "Section 4 of the CVC Act, 2003 sets this committee. The CJI sits on the committee for the CBI Director, not the CVC.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-constitutional-bodies-62", "question": "The Director of the CBI is appointed on the recommendation of a committee consisting of the:", "options": ["Prime Minister, Union Home Minister and Central Vigilance Commissioner", "Prime Minister, Leader of the Opposition (or leader of the largest opposition party) in the Lok Sabha, and the Chief Justice of India or a judge nominated by him", "Union Home Minister, Cabinet Secretary and Central Vigilance Commissioner", "President, Prime Minister and Speaker"], "answer": 1, "explanation": "The Lokpal and Lokayuktas Act, 2013 amended the Delhi Special Police Establishment Act to create this committee; earlier the CVC-led committee recommended the Director.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-constitutional-bodies-63", "question": "The CAG's reports relating to the accounts of a State are submitted to the:", "options": ["President", "Chief Minister", "Governor", "Speaker of the State Assembly"], "answer": 2, "explanation": "Article 151(2) says the State reports go to the Governor, who lays them before the State legislature. Union reports go to the President.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-constitutional-bodies-64", "question": "After the Protection of Human Rights (Amendment) Act, 2019, the Chairperson and members of the NHRC hold office for:", "options": ["Five years or until 70", "Three years or until 70", "Five years or until 65", "Three years or until 65"], "answer": 1, "explanation": "The 2019 amendment cut the term from five years to three years, with an upper age limit of 70, and allowed reappointment.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-constitutional-bodies-65", "question": "The Chairperson of a State Human Rights Commission is appointed by the Governor but can be removed only by the:", "options": ["Governor", "Chief Minister", "President", "Chief Justice of the High Court"], "answer": 2, "explanation": "Under Section 23 of the Protection of Human Rights Act, 1993, the SHRC Chairperson and members can be removed only by the President, which protects their independence.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-constitutional-bodies-66", "question": "Under the RTI rules notified in 2019, the Chief Information Commissioner holds office for:", "options": ["Five years", "Four years", "Three years", "Six years"], "answer": 2, "explanation": "The RTI (Amendment) Act, 2019 let the Centre fix the term, and the 2019 rules set it at three years (the original Act had five years or age 65).", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-constitutional-bodies-67", "question": "In Anoop Baranwal v. Union of India (2023), the Supreme Court directed that, until Parliament made a law, the CEC and Election Commissioners be appointed on the advice of a committee of the:", "options": ["Prime Minister, a Union Cabinet minister and the Leader of the Opposition", "Prime Minister, the Leader of the Opposition (or of the largest opposition party) and the Chief Justice of India", "President, Prime Minister and Speaker", "Chief Justice of India and two senior-most judges"], "answer": 1, "explanation": "The Court's interim arrangement included the CJI. The 2023 Act that followed replaced the CJI with a Union Cabinet minister nominated by the PM.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-constitutional-bodies-68", "question": "Match the Article with the body it provides for: A. Article 315 B. Article 324 C. Article 338A D. Article 350B — 1. Special Officer for Linguistic Minorities 2. National Commission for Scheduled Tribes 3. Election Commission 4. Public Service Commissions", "options": ["A-3, B-4, C-2, D-1", "A-4, B-2, C-3, D-1", "A-4, B-3, C-1, D-2", "A-4, B-3, C-2, D-1"], "answer": 3, "explanation": "Article 315 is Public Service Commissions, 324 the Election Commission, 338A the NCST (89th Amendment) and 350B the Special Officer for Linguistic Minorities.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-constitutional-bodies-69", "question": "How many of these are statutory (not constitutional) bodies in 2026? I. National Commission for Women II. National Commission for Minorities III. National Commission for Backward Classes IV. Central Vigilance Commission", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "The NCW (1990 Act), NCM (1992 Act) and CVC (2003 Act) are statutory. The NCBC was statutory under a 1993 Act but became constitutional under Article 338B in 2018.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-constitutional-bodies-70", "question": "Assertion (A): A Joint State Public Service Commission is a statutory body. Reason (R): It is created by an Act of Parliament at the request of the legislatures of the States concerned.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is true, but R is false", "A is false, but R is true"], "answer": 0, "explanation": "Both are true and R explains A: Article 315(2) lets Parliament create a JSPSC by law on a resolution of each State legislature concerned, so the body itself rests on that law. Its chairman and members are appointed by the President.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-constitutional-bodies-71", "question": "Arrange in time order: 1. National Commission for Women constituted 2. Central Bureau of Investigation set up 3. First Chairperson of the Lokpal appointed 4. Central Vigilance Commission given statutory status", "options": ["2-1-4-3", "1-2-4-3", "2-4-1-3", "2-1-3-4"], "answer": 0, "explanation": "CBI (1963), NCW (1992), CVC statutory status (2003), first Lokpal Chairperson (2019).", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-constitutional-bodies-72", "question": "How many of these statements about the Chief Election Commissioner and Other Election Commissioners Act, 2023 are correct? I. A Search Committee headed by the Union Law Minister prepares a panel of five names. II. The Selection Committee may consider a person outside that panel. III. The CEC holds office for six years or until 65, whichever is earlier. IV. The CEC can be removed only like a Supreme Court judge, and an Election Commissioner only on the CEC's recommendation.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct. The removal protections come from the proviso to Article 324(5), which the Act retains.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-constitutional-bodies-73", "question": "Assertion (A): The Election Commission recognises political parties and allots election symbols. Reason (R): The Election Symbols (Reservation and Allotment) Order, 1968 was issued by the Commission under Article 324 read with election law.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is true, but R is false", "A is false, but R is true"], "answer": 0, "explanation": "Both are true and R explains A: the Symbols Order, made under the Commission's plenary powers of superintendence, direction and control, governs recognition and symbols.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-constitutional-bodies-74", "question": "Match the body with the law it was set up under: A. Central Vigilance Commission B. National Commission for Minorities C. National Human Rights Commission D. Central Information Commission — 1. Right to Information Act, 2005 2. Protection of Human Rights Act, 1993 3. National Commission for Minorities Act, 1992 4. Central Vigilance Commission Act, 2003", "options": ["A-4, B-3, C-2, D-1", "A-4, B-3, C-1, D-2", "A-4, B-2, C-3, D-1", "A-3, B-4, C-2, D-1"], "answer": 0, "explanation": "The CVC was first created by a 1964 resolution and made statutory in 2003; the NCM by the 1992 Act, the NHRC by the 1993 Act and the CIC by the RTI Act, 2005.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-constitutional-bodies-75", "question": "How many of these statements about the Delimitation Commission are correct? I. It has been set up four times: in 1952, 1963, 1973 and 2002. II. Its orders have the force of law and cannot be questioned in any court. III. The 2002 Commission redrew constituency boundaries but did not change the number of seats per State. IV. It is a permanent constitutional body.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct. IV is wrong: it is set up by an Act of Parliament after each Census when Parliament so decides (Article 82), and ceases to exist after its work.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-constitutional-bodies-76", "question": "Which of these office-holders is NOT appointed by the President?", "options": ["Comptroller and Auditor General", "Chairman of a State Public Service Commission", "Attorney General for India", "Chief Election Commissioner"], "answer": 1, "explanation": "The Chairman and members of a State PSC are appointed by the Governor (Article 316), though only the President can remove them. The others are presidential appointments.", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "polity-constitutional-bodies-77", "question": "How many of these statements about the National Commission for Scheduled Castes are correct? I. It is provided for in Article 338. II. It investigates and monitors matters relating to safeguards for Scheduled Castes. III. While investigating a complaint it has all the powers of a civil court. IV. It submits its reports directly to Parliament.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III (Article 338(5) and (8)) are correct. IV is wrong: reports go to the President, who has them laid before each House with a memorandum on action taken.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-constitutional-bodies-78", "question": "Match the office with how it can be removed: A. Chief Election Commissioner B. An Election Commissioner C. Member of a State PSC D. Attorney General for India — 1. By the President at pleasure 2. By the President after an inquiry by the Supreme Court (for misbehaviour) 3. By the President on the recommendation of the CEC 4. In the same manner and on the same grounds as a Supreme Court judge", "options": ["A-4, B-3, C-2, D-1", "A-3, B-4, C-2, D-1", "A-4, B-2, C-3, D-1", "A-4, B-3, C-1, D-2"], "answer": 0, "explanation": "The CEC is removed like a Supreme Court judge, an EC on the CEC's recommendation (Article 324(5)), a State PSC member by the President after a Supreme Court inquiry (Article 317), and the AG holds office at the President's pleasure (Article 76(4)).", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-constitutional-bodies-79", "question": "Assertion (A): The Advocate General can speak in and take part in the proceedings of the State Legislative Assembly. Reason (R): Article 177 gives the Advocate General the right to speak and take part in the proceedings of the State legislature, without a right to vote.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is true, but R is false", "A is false, but R is true"], "answer": 0, "explanation": "Both are true and R explains A. Article 177 is the State counterpart of Article 88, which gives the same right to the Attorney General in Parliament.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-constitutional-bodies-80", "question": "How many of these statements about the Central Vigilance Commission are correct? I. It consists of a Central Vigilance Commissioner and up to two Vigilance Commissioners. II. They hold office for four years or until 65, whichever is earlier. III. They can be removed by the President for proved misbehaviour or incapacity after a Supreme Court inquiry. IV. It exercises superintendence over the CBI's investigations of offences under the Prevention of Corruption Act.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct under the CVC Act, 2003 (Sections 3, 5, 6 and 8).", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-constitutional-bodies-81", "question": "Arrange these Amendments in time order: 1. The 89th Amendment creating a separate National Commission for STs 2. The 7th Amendment providing a Special Officer for Linguistic Minorities 3. The 102nd Amendment giving the NCBC constitutional status 4. The 65th Amendment replacing the Special Officer for SCs and STs with a multi-member National Commission", "options": ["2-4-3-1", "2-1-4-3", "4-2-1-3", "2-4-1-3"], "answer": 3, "explanation": "7th Amendment (1956), 65th (1990), 89th (2003) and 102nd (2018).", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-constitutional-bodies-82", "question": "How many of these are required by the Constitution to be laid before each House of Parliament? I. The CAG's audit reports on the Union accounts II. The UPSC's annual report, with a memorandum on cases where its advice was not accepted III. The National Commission for Scheduled Castes' reports IV. The Finance Commission's recommendations, with an explanatory memorandum on action taken", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four: Articles 151(1), 323(1), 338(6) and 281 respectively.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-constitutional-bodies-83", "question": "Which pair of body and its chairperson is NOT correctly matched?", "options": ["NITI Aayog – Prime Minister", "GST Council – Union Finance Minister", "Zonal Council – Prime Minister", "Inter-State Council – Prime Minister"], "answer": 2, "explanation": "Zonal Councils, set up under the States Reorganisation Act, 1956, are chaired by the Union Home Minister. The other three are correctly matched.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-constitutional-bodies-84", "question": "How many of these statements about the law officers are correct? I. The Attorney General has the right of audience in all courts in India. II. The Solicitor General is appointed on the approval of the Appointments Committee of the Cabinet. III. The Advocate General's remuneration is determined by the Governor. IV. The Constitution fixes the Attorney General's salary.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I (Article 76(3)), II and III (Article 165(3)) are correct. IV is wrong: the AG receives whatever remuneration the President determines (Article 76(4)); no salary is fixed.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-constitutional-bodies-85", "question": "Match the Article with its subject: A. Article 148 B. Article 149 C. Article 150 D. Article 151 — 1. Audit reports 2. Form of accounts of the Union and the States 3. Duties and powers of the CAG 4. Appointment of the CAG", "options": ["A-4, B-2, C-3, D-1", "A-4, B-3, C-2, D-1", "A-4, B-3, C-1, D-2", "A-3, B-4, C-2, D-1"], "answer": 1, "explanation": "Article 148 is appointment, 149 duties and powers, 150 the form of accounts (prescribed by the President on the CAG's advice) and 151 the audit reports.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-constitutional-bodies-86", "question": "Who was the first Chief Election Commissioner of India, who conducted the first general election of 1951–52?", "options": ["Sukumar Sen", "T. N. Seshan", "K. V. K. Sundaram", "S. P. Sen Verma"], "answer": 0, "explanation": "Sukumar Sen was CEC from 1950 to 1958 and ran the first two general elections. K. V. K. Sundaram succeeded him; T. N. Seshan was CEC from 1990 to 1996.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "polity-constitutional-bodies-87", "question": "National Voters' Day, which marks the founding of the Election Commission of India, is observed on:", "options": ["26 November", "25 January", "15 March", "2 October"], "answer": 1, "explanation": "The Election Commission was set up on 25 January 1950, a day before the Constitution came into force; National Voters' Day has been observed on that date since 2011.", "difficulty": "easy", "source": "SSC CGL · RRB NTPC"},
  {"id": "polity-constitutional-bodies-88", "question": "Who was the first Attorney General for India?", "options": ["C. K. Daphtary", "Soli Sorabjee", "K. K. Venugopal", "M. C. Setalvad"], "answer": 3, "explanation": "M. C. Setalvad served from 1950 to 1963, the longest tenure in the office. C. K. Daphtary succeeded him.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL"},
  {"id": "polity-constitutional-bodies-89", "question": "The GST Council is a constitutional body under which Article, inserted by the 101st Amendment (2016)?", "options": ["Article 263", "Article 269A", "Article 279A", "Article 280"], "answer": 2, "explanation": "Article 279A creates the GST Council, chaired by the Union Finance Minister. Article 269A, also inserted in 2016, deals with GST on inter-State supplies; Article 280 is the Finance Commission.", "difficulty": "moderate", "source": "SSC CGL · State PSCs"},
  {"id": "polity-constitutional-bodies-90", "question": "The Inter-State Council under Article 263 was first set up in 1990 on the recommendation of the:", "options": ["Sarkaria Commission", "Punchhi Commission", "Rajamannar Committee", "First Administrative Reforms Commission"], "answer": 0, "explanation": "The Sarkaria Commission on Centre–State relations (report 1988) recommended a permanent Inter-State Council, which the President set up by order in 1990. The Punchhi Commission reported in 2010.", "difficulty": "moderate", "source": "SSC CGL · State PSCs"},
  {"id": "polity-constitutional-bodies-91", "question": "The Zonal Councils are:", "options": ["Constitutional bodies under Article 263", "Statutory bodies under the States Reorganisation Act, 1956", "Executive bodies set up by a Cabinet resolution of 1950", "Bodies created by the North Eastern Council Act, 1971"], "answer": 1, "explanation": "The five Zonal Councils were created by the States Reorganisation Act, 1956 and are chaired by the Union Home Minister. The North Eastern Council is a separate statutory body under its 1971 Act.", "difficulty": "moderate", "source": "SSC CGL · State PSCs"},
  {"id": "polity-constitutional-bodies-92", "question": "Who was the first Comptroller and Auditor General of India?", "options": ["A. K. Chanda", "Vinod Rai", "V. Narahari Rao", "T. N. Chaturvedi"], "answer": 2, "explanation": "V. Narahari Rao was the first CAG (1948–54). A. K. Chanda succeeded him; Vinod Rai served from 2008 to 2013.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "polity-constitutional-bodies-93", "question": "The CAG is often described as the “friend, philosopher and guide” of which parliamentary committee?", "options": ["Estimates Committee", "Public Accounts Committee", "Committee on Public Undertakings", "Business Advisory Committee"], "answer": 1, "explanation": "The Public Accounts Committee examines the CAG's audit reports, and the CAG assists it in that work. The CAG is not a member of the committee.", "difficulty": "moderate", "source": "SSC CGL · State PSCs"},
  {"id": "polity-constitutional-bodies-94", "question": "Who was the first Chairperson of the National Human Rights Commission?", "options": ["Ranganath Misra", "M. N. Venkatachaliah", "J. S. Verma", "K. G. Balakrishnan"], "answer": 0, "explanation": "Former CJI Ranganath Misra headed the NHRC when it was set up in October 1993. Venkatachaliah and Verma were later chairpersons.", "difficulty": "moderate", "source": "SSC CGL · State PSCs"},
  {"id": "polity-constitutional-bodies-95", "question": "In Association for Democratic Reforms v. Union of India (February 2024), a five-judge bench of the Supreme Court:", "options": ["Upheld the Electoral Bond Scheme", "Referred the scheme to a seven-judge bench", "Asked the Election Commission to frame a new scheme", "Struck down the Electoral Bond Scheme as violating voters' right to information"], "answer": 3, "explanation": "The unanimous bench held the anonymous bond scheme violated Article 19(1)(a) and directed the SBI to disclose bond data to the Election Commission for publication.", "difficulty": "moderate", "source": "UPSC Prelims · State PSCs"},
  {"id": "polity-constitutional-bodies-96", "question": "Which community was notified as a minority under the National Commission for Minorities Act, 1992 in 2014, raising the number of notified minorities to six?", "options": ["Sikhs", "Parsis", "Jains", "Buddhists"], "answer": 2, "explanation": "Muslims, Christians, Sikhs, Buddhists and Parsis were notified in 1993; Jains were added in 2014. The NCM is a statutory body, not a constitutional one.", "difficulty": "hard", "source": "UPSC Prelims · State PSCs"},
  {"id": "polity-constitutional-bodies-97", "question": "Under Article 316, as nearly as may be, what share of the members of a Public Service Commission must have held office under the Government of India or a State for at least ten years?", "options": ["One-third", "One-half", "Two-thirds", "At least one member"], "answer": 1, "explanation": "The proviso to Article 316(1) requires about half the members to have ten years of government service. The Constitution prescribes no other qualification.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "polity-constitutional-bodies-98", "question": "The duties and powers of the CAG are set out in the CAG (Duties, Powers and Conditions of Service) Act passed in:", "options": ["1950", "1976", "1971", "1984"], "answer": 2, "explanation": "Parliament passed the Act in 1971 under Article 149. A 1976 amendment relieved the CAG of compiling Union accounts, separating accounting from audit.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "polity-constitutional-bodies-99", "question": "Who was the first Chief Information Commissioner of India?", "options": ["Wajahat Habibullah", "A. N. Tiwari", "Satyananda Mishra", "Deepak Sandhu"], "answer": 0, "explanation": "Wajahat Habibullah headed the Central Information Commission from 2005. Deepak Sandhu was the first woman CIC (2013).", "difficulty": "hard", "source": "SSC CGL · State PSCs"},
  {"id": "polity-constitutional-bodies-100", "question": "Which 1997 judgment led to statutory status for the Central Vigilance Commission and a fixed tenure for the CBI Director?", "options": ["Prakash Singh v. Union of India", "Anoop Baranwal v. Union of India", "Common Cause v. Union of India", "Vineet Narain v. Union of India"], "answer": 3, "explanation": "Vineet Narain (the Jain hawala case) directed reforms that were later given effect by the Central Vigilance Commission Act, 2003. Prakash Singh (2006) concerned police reform.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "polity-constitutional-bodies-101", "question": "The CBI derives its legal powers of investigation from:", "options": ["The Central Bureau of Investigation Act, 1963", "A constitutional provision in Part XIV", "The Delhi Special Police Establishment Act, 1946", "The Central Vigilance Commission Act, 2003"], "answer": 2, "explanation": "There is no CBI Act. The CBI was set up by a Home Ministry resolution on 1 April 1963 and investigates under the Delhi Special Police Establishment Act, 1946.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "polity-constitutional-bodies-102", "question": "Electors Photo Identity Cards were introduced in 1993 when the Chief Election Commissioner was:", "options": ["T. N. Seshan", "M. S. Gill", "J. M. Lyngdoh", "R. V. S. Peri Sastri"], "answer": 0, "explanation": "T. N. Seshan (1990–96) pushed through EPICs and strict enforcement of the Model Code of Conduct. M. S. Gill succeeded him.", "difficulty": "hard", "source": "SSC CGL · State PSCs"},
  {"id": "polity-constitutional-bodies-103", "question": "The “None of the Above” (NOTA) option was added to ballot papers and EVMs following the Supreme Court judgment in:", "options": ["Lily Thomas v. Union of India (2013)", "PUCL v. Union of India (2013)", "Anoop Baranwal v. Union of India (2023)", "Union of India v. ADR (2002)"], "answer": 1, "explanation": "PUCL (2013) held that the right not to vote for any candidate is part of expression and must be secret. Lily Thomas (2013) dealt with disqualification of convicted legislators.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "polity-constitutional-bodies-104", "question": "Electronic voting machines were first used in India in 1982 in a by-election in:", "options": ["Noksen, Nagaland", "Thiruvananthapuram, Kerala", "Bhopal, Madhya Pradesh", "Paravur, Kerala"], "answer": 3, "explanation": "EVMs were first used in some polling stations of the Paravur Assembly constituency in Kerala in 1982. VVPATs were first used at Noksen, Nagaland in 2013.", "difficulty": "hard", "source": "SSC CGL · State PSCs"},
  {"id": "polity-constitutional-bodies-105", "question": "Consider the following statements: 1. The Fourteenth Finance Commission raised the States' share in the divisible pool of central taxes to 42%. 2. The Fifteenth Finance Commission recommended 41%, adjusting for Jammu and Kashmir becoming a Union Territory. Which of the above is/are correct?", "options": ["1 only", "2 only", "Both 1 and 2", "Neither 1 nor 2"], "answer": 2, "explanation": "Both are correct. The Fourteenth (Y. V. Reddy) raised the share from 32% to 42%; the Fifteenth (N. K. Singh) set 41%.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-constitutional-bodies-106", "question": "Consider the following statements: 1. The Finance Commission recommends measures to augment a State's Consolidated Fund to supplement the resources of panchayats and municipalities. 2. This function has been part of Article 280 since 1950. Which of the above is/are correct?", "options": ["1 only", "2 only", "Both 1 and 2", "Neither 1 nor 2"], "answer": 0, "explanation": "Only 1 is correct. Clauses (bb) and (c) of Article 280(3) were added by the 73rd and 74th Amendments in 1992.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-constitutional-bodies-107", "question": "Arrange in chronological order: 1. The 89th Amendment creates a separate National Commission for Scheduled Tribes 2. A Special Officer for SCs and STs is appointed under the original Article 338 3. The 65th Amendment creates a multi-member National Commission for SCs and STs 4. The 102nd Amendment gives constitutional status to the National Commission for Backward Classes", "options": ["2, 3, 1, 4", "3, 2, 1, 4", "2, 1, 3, 4", "2, 3, 4, 1"], "answer": 0, "explanation": "Special Officer (from 1950), 65th Amendment (1990), 89th Amendment (2003) and 102nd Amendment (2018).", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-constitutional-bodies-108", "question": "How many of these statements about the CAG are correct? I. The CAG's duties are laid down in an Act of 1971. II. Since 1976 the CAG no longer compiles the accounts of the Union. III. After leaving office, the CAG cannot hold any further office under the Government of India or a State. IV. The CAG is an ex officio member of the Public Accounts Committee.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct (III is Article 148(4)). IV is wrong: the CAG assists the PAC but is not its member.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-constitutional-bodies-109", "question": "Consider the following statements about removing a UPSC member: 1. The President can remove a member who is adjudged insolvent without referring the matter to the Supreme Court. 2. For removal on the ground of misbehaviour, the Supreme Court's advice after inquiry is only advisory and does not bind the President. Which of the above is/are correct?", "options": ["1 only", "2 only", "Both 1 and 2", "Neither 1 nor 2"], "answer": 0, "explanation": "Only 1 is correct under Article 317(3). For misbehaviour, the Supreme Court's advice after inquiry under Article 317(1) is binding on the President.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-constitutional-bodies-110", "question": "Match the body with its nature: A. GST Council B. Inter-State Council C. Zonal Council D. NITI Aayog — 1. Executive body set up by a Cabinet resolution 2. Statutory body 3. Set up by Presidential order under a constitutional provision 4. Constitutional body created directly by Article 279A", "options": ["A-4, B-3, C-1, D-2", "A-3, B-4, C-2, D-1", "A-4, B-3, C-2, D-1", "A-4, B-2, C-3, D-1"], "answer": 2, "explanation": "The GST Council is created by Article 279A itself; the Inter-State Council was set up by Presidential order under Article 263; Zonal Councils are statutory (1956 Act); NITI Aayog rests on a 2015 Cabinet resolution.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-constitutional-bodies-111", "question": "Assertion (A): No person can be left out of the electoral roll on grounds only of religion, race, caste or sex. Reason (R): Article 325 provides for one general electoral roll for every territorial constituency, ending separate communal electorates.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Both are true and R explains A. Article 325 replaced the separate electorates of the colonial period with a single roll; Article 326 separately provides adult suffrage.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-constitutional-bodies-112", "question": "Arrange in chronological order: 1. Central Vigilance Commission gets statutory status 2. GST Council constituted 3. National Human Rights Commission set up 4. Inter-State Council set up", "options": ["3, 4, 1, 2", "4, 1, 3, 2", "4, 3, 2, 1", "4, 3, 1, 2"], "answer": 3, "explanation": "Inter-State Council (1990), NHRC (1993), CVC Act (2003) and GST Council (2016).", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-constitutional-bodies-113", "question": "Consider the following statements: 1. The National Commission for Minorities was given constitutional status by the 102nd Amendment. 2. Jains were notified as a minority community in 2014. Which of the above is/are correct?", "options": ["1 only", "2 only", "Both 1 and 2", "Neither 1 nor 2"], "answer": 1, "explanation": "Only 2 is correct. The 102nd Amendment (2018) gave constitutional status to the National Commission for Backward Classes (Article 338B); the NCM remains statutory.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-constitutional-bodies-114", "question": "Consider the following statements about the Inter-State Council: 1. It is chaired by the Prime Minister. 2. Its Standing Committee is chaired by the Union Home Minister. Which of the above is/are correct?", "options": ["1 only", "2 only", "Both 1 and 2", "Neither 1 nor 2"], "answer": 2, "explanation": "Both are correct. Its members include the Chief Ministers of all States and of UTs with legislatures, administrators of other UTs and Union ministers nominated by the PM.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-constitutional-bodies-115", "question": "Who was the first woman to serve as Chief Election Commissioner of India, briefly in 1990?", "options": ["Kiran Bedi", "Sheila Dikshit", "Najma Heptulla", "V. S. Ramadevi"], "answer": 3, "explanation": "V. S. Ramadevi held the office for about two weeks in November–December 1990, before T. N. Seshan took over. She later became Governor of Himachal Pradesh and Karnataka.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id":"polity-constitutional-bodies-116","question":"Consider the following statements about employment after leaving a Public Service Commission (Article 319): 1. The Chairman of the UPSC is not eligible for any further employment under the Government of India or a State. 2. A member of the UPSC, other than the Chairman, may be appointed Chairman of the UPSC or of a State PSC, but to no other government post. 3. The Chairman of a State PSC may take up any other employment under the State Government. Which of the above are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"Article 319 lets a State PSC Chairman move only to the UPSC (as Chairman or member) or to chair another State PSC, not to other employment. Statements 1 and 2 are accurate.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-117","question":"The Union Government decides not to accept a piece of advice given by the UPSC. Which statement correctly describes the constitutional consequence?","options":["The case appears in the memorandum, laid before each House with the UPSC's annual report, explaining why the advice was not accepted","The UPSC may move the Supreme Court to enforce its advice","The advice is binding, so the Government must seek Parliament's approval to depart from it","The President must refer the matter to the Supreme Court under Article 143"],"answer":0,"explanation":"UPSC advice is not binding. Article 323 provides only accountability: the President lays the report with a memorandum explaining the cases of non-acceptance and the reasons.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-118","question":"Under Article 321, an Act of Parliament may extend the functions of the UPSC to cover:","options":["the conduct of elections to local bodies","appeals against decisions of the Central Administrative Tribunal","the services of a local authority, a statutory corporation or a public institution","recruitment to the judicial services of the States"],"answer":2,"explanation":"Article 321 allows additional functions for the services of the Union and of local authorities, bodies corporate set up by law and public institutions. Local elections belong to State Election Commissions.","difficulty":"moderate","source":"UPSC Prelims · SSC CGL"},
  {"id":"polity-constitutional-bodies-119","question":"If the office of Chairman of the UPSC falls vacant, who performs the duties of the office until a new Chairman takes over?","options":["One of the other members, appointed by the President for this purpose","The senior-most member, automatically","The Secretary of the UPSC","A retired Supreme Court judge nominated by the Chief Justice of India"],"answer":0,"explanation":"Article 316(1A) has the President appoint one of the other members to perform the duties. There is no automatic seniority rule.","difficulty":"moderate","source":"UPSC Prelims · State PSCs"},
  {"id":"polity-constitutional-bodies-120","question":"Consider the following statements about a Joint State Public Service Commission: 1. Its Chairman and members are appointed by the President. 2. Its members hold office until the age of 62. 3. It presents its annual report to the President. Which of the above are correct?","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"answer":0,"explanation":"A Joint Commission is appointed by the President and follows the State PSC age limit of 62. Under Article 323(2) it reports to the Governor of each State it serves, not to the President.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-121","question":"Can the UPSC take up the recruitment needs of a State?","options":["No, the Constitution confines the UPSC strictly to Union services","Yes, but only during a National Emergency","Yes, if the State legislature passes a resolution by a special majority","Yes, if the Governor requests it and the President approves"],"answer":3,"explanation":"Article 315(4) lets the UPSC agree to serve all or any of a State's needs on the Governor's request, with the President's approval.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-122","question":"In the Third Schedule, the form of oath or affirmation of the Comptroller and Auditor General is the same form as that of:","options":["Union ministers","Judges of the Supreme Court","Members of Parliament","The Attorney General for India"],"answer":1,"explanation":"Form IV of the Third Schedule covers both Supreme Court judges and the CAG, underlining the CAG's independence. The Attorney General takes no oath under the Third Schedule.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-123","question":"Consider the following statements about the CAG: 1. The CAG's salary is determined by Parliament by law. 2. The administrative expenses of the CAG's office, including staff salaries and pensions, are charged on the Consolidated Fund of India. 3. Parliament may vary the CAG's leave and pension rights to his disadvantage during his term. Which of the above are correct?","options":["1 only","2 and 3 only","1 and 2 only","1, 2 and 3"],"answer":2,"explanation":"Article 148(3) bars any change to the CAG's disadvantage after appointment, so 3 is wrong. Article 148(6) charges the office's expenses on the Consolidated Fund.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-124","question":"Under Article 279, the ‘net proceeds’ of a tax, which decide what is shared with the States, are ascertained and certified by:","options":["the Finance Commission","the Union Ministry of Finance","the GST Council","the Comptroller and Auditor General, whose certificate is final"],"answer":3,"explanation":"Article 279(1) makes the CAG's certificate of net proceeds final. The Finance Commission recommends the share, but does not certify the amount.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-125","question":"Which statement best captures how India's CAG differs from the British Comptroller and Auditor-General?","options":["The Indian CAG is also a member of the Public Accounts Committee","The Indian CAG is only an auditor and has no control over the release of money from the Consolidated Fund","The Indian CAG must approve every withdrawal from the Consolidated Fund in advance","The Indian CAG is an officer of Parliament, appointed by the Speaker"],"answer":1,"explanation":"The British office also controls the issue of public money; in India the executive withdraws money without the CAG's sanction, and the CAG audits afterwards. He is appointed by the President, not the Speaker.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-126","question":"Which type of audit carried out by the CAG is generally described as discretionary rather than obligatory?","options":["Propriety audit, checking wisdom, faithfulness and economy of expenditure","Legal and regulatory audit","Appropriation audit, checking spending against the grants voted","Audit of the accounts of the Contingency Fund"],"answer":0,"explanation":"Legal, regulatory and appropriation audits are obligatory. Propriety audit, which looks at whether spending was wise and economical, is at the CAG's discretion.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-127","question":"Which of these is true of the Attorney General for India but NOT of the Advocate General of a State?","options":["Holds office during the pleasure of the appointing authority","Receives such remuneration as the appointing authority determines","Must be qualified to be appointed a judge of the Supreme Court","May speak in the legislature without the right to vote"],"answer":2,"explanation":"The Advocate General needs only the qualifications of a High Court judge (Article 165). The other three features are common to both offices (Articles 76, 88, 165, 177).","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-128","question":"Under the Finance Commission (Miscellaneous Provisions) Act, 1951, the Chairman of the Finance Commission must be a person who has had:","options":["special knowledge of economics","the qualifications of a Supreme Court judge","service as Governor of the Reserve Bank of India","experience in public affairs"],"answer":3,"explanation":"The Act requires the Chairman to have experience in public affairs. The four members are drawn from High Court judges (or persons qualified), and experts in government finance, financial administration and economics.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-129","question":"In the GST Council, the Union's vote counts for one-third of votes cast, all States together for two-thirds, and a decision needs three-fourths of the weighted votes of members present and voting. What follows?","options":["The States acting together can carry any decision without the Union","The Union can block any proposal, and the States acting together cannot carry one without the Union","The Union can carry any decision on its own if a few States support it","Neither side can block a proposal; every decision needs only a simple majority of States"],"answer":1,"explanation":"One-third exceeds one-quarter, so the Union alone can block. Two-thirds falls short of three-quarters, so the States alone cannot pass a proposal.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-130","question":"In Union of India v. Mohit Minerals (2022), the Supreme Court held that the GST Council's recommendations:","options":["bind Parliament and the State legislatures under Article 279A","bind the States but not Parliament","are persuasive, not binding, and both Parliament and the States can legislate on GST","can be challenged only before the GST Appellate Tribunal"],"answer":2,"explanation":"The Court read Article 279A as making the Council a forum for cooperative federalism; its recommendations carry persuasive value, and Article 246A lets both levels legislate.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-131","question":"Who presides over each of the Zonal Councils set up under the States Reorganisation Act, 1956?","options":["The Prime Minister","The Chief Minister of the largest State in the zone","The Vice-Chairperson of NITI Aayog","The Union Home Minister"],"answer":3,"explanation":"The Union Home Minister chairs every Zonal Council; the Chief Ministers of the member States take turns as Vice-Chairman. They are statutory, not constitutional, bodies.","difficulty":"moderate","source":"UPSC Prelims · SSC CGL"},
  {"id":"polity-constitutional-bodies-132","question":"Under Article 324(4), before a general election, Regional Commissioners may be appointed to assist the Election Commission. Who appoints them?","options":["The President, after consulting the Election Commission","The Chief Election Commissioner, on his own","The Governors of the States concerned","The President, on the advice of the Union Home Ministry alone"],"answer":0,"explanation":"Regional Commissioners are appointed by the President after consulting the Election Commission. Under Article 324(5) they can be removed only on the CEC's recommendation.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-133","question":"In T. N. Seshan v. Union of India (1995), the Supreme Court held that:","options":["the CEC has a casting vote that overrides the other Election Commissioners","the multi-member Election Commission is valid, and it decides by majority, the CEC not being superior in decision-making","the Election Commission must always have exactly three members","the appointment of additional Election Commissioners requires Parliament's approval"],"answer":1,"explanation":"The Court upheld the multi-member Commission and majority decisions. The CEC's stronger protection against removal does not make him superior to the other Commissioners.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-134","question":"Consider the following statements: 1. Whether an MP has incurred a disqualification under Article 102(1), such as holding an office of profit, is decided by the President. 2. In deciding such a question, the President must act according to the opinion of the Election Commission. 3. Disqualification of an MP for defection is also decided by the President on the Election Commission's opinion. Which of the above are correct?","options":["1 only","2 and 3 only","1, 2 and 3","1 and 2 only"],"answer":3,"explanation":"Article 103 gives the President the decision and binds him to the Election Commission's opinion. Defection under the Tenth Schedule is decided by the Speaker or Chairman instead.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-135","question":"Which of these is governed by the Representation of the People Act, 1950, rather than the Act of 1951?","options":["Corrupt practices at elections","Election petitions","Preparation of electoral rolls","Disqualification of members on conviction"],"answer":2,"explanation":"The 1950 Act deals with allocation of seats, delimitation, voter qualifications and electoral rolls. The 1951 Act covers the conduct of elections, disqualifications, corrupt practices and disputes.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-136","question":"The Chief Electoral Officer of a State is:","options":["designated or nominated by the Election Commission of India in consultation with the State Government","appointed by the Governor on the advice of the Chief Minister","appointed by the State Election Commissioner","appointed by the President on the advice of the Union Law Ministry"],"answer":0,"explanation":"Under Section 13A of the Representation of the People Act, 1950, the ECI designates the CEO in consultation with the State Government; he works under the ECI's superintendence.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-137","question":"Consider the following statements: 1. The Election Commission of India conducts elections to Panchayats. 2. A State Election Commissioner is appointed by the Governor and can be removed only in the manner of a High Court judge. 3. The Election Commission of India conducts the election to the office of Vice-President. Which of the above are correct?","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"answer":1,"explanation":"Panchayat and municipal elections belong to the State Election Commission (Articles 243K and 243ZA). The ECI's Article 324 mandate covers Parliament, State legislatures, President and Vice-President.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-138","question":"Under the Delimitation Act, 2002, the Delimitation Commission consists of:","options":["the CEC as Chairperson, the Union Law Secretary and the Registrar General of India","a sitting High Court judge as Chairperson, the CEC and the Chief Secretary of the State","a serving or retired Supreme Court judge as Chairperson, the CEC or an Election Commissioner nominated by him, and the State Election Commissioner of the State concerned","a retired Chief Justice of India as Chairperson and two members nominated by the Speaker"],"answer":2,"explanation":"The Chairperson is a present or former Supreme Court judge; the CEC (or his nominee) and the State Election Commissioner of the State being delimited are ex officio members.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-139","question":"Which of the following is NOT a deemed member of the National Human Rights Commission?","options":["Chairperson of the National Commission for Women","Chairperson of the National Commission for Minorities","Chief Commissioner for Persons with Disabilities","Chief Information Commissioner"],"answer":3,"explanation":"Deemed members are the chairpersons of the commissions for SCs, STs, Women, Minorities, Backward Classes and Child Rights, plus the Chief Commissioner for Persons with Disabilities. The CIC is not one.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-140","question":"Which of these is NOT a member of the committee that recommends the appointment of the NHRC Chairperson?","options":["Deputy Chairman of the Rajya Sabha","Chief Justice of India","Union Home Minister","Leader of the Opposition in the Rajya Sabha"],"answer":1,"explanation":"The committee is the PM, Speaker, Union Home Minister, Leaders of the Opposition in both Houses and the Rajya Sabha's Deputy Chairman. The CJI is only consulted before a sitting judge is appointed.","difficulty":"moderate","source":"UPSC Prelims · State PSCs"},
  {"id":"polity-constitutional-bodies-141","question":"Which statement about the Model Code of Conduct for elections is correct?","options":["It has no statutory backing and comes into force when the Election Commission announces the election schedule","It is part of the Representation of the People Act, 1951 and is enforced by the courts","It comes into force only when the formal election notification is issued","It applies to political parties but not to the governments in office"],"answer":0,"explanation":"The MCC grew by consensus among parties and is not a statute. Following Harbans Singh Jalal (2001), it operates from the announcement of the schedule, and it binds ruling governments too.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-142","question":"Under Section 20 of the Right to Information Act, 2005, when an Information Commission finds that information was refused or delayed without reasonable cause, what penalty can it impose?","options":["₹250 for each day of delay, up to a total of ₹25,000, on the Public Information Officer","₹500 for each day of delay, up to ₹50,000, on the public authority","₹250 for each day of delay, with no upper limit, on the head of the department","₹1,000 for each day of delay, up to ₹25,000, on the appellate authority"],"answer":0,"explanation":"The penalty is personal to the PIO: ₹250 a day, capped at ₹25,000. Compensation to the applicant from the public authority is a separate power.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-143","question":"Under the RTI Act, 2005, an applicant unhappy with a Public Information Officer's decision may file:","options":["a second appeal directly to the High Court within 30 days","a first appeal to the Information Commission within 90 days, and then a writ petition","a first appeal within 30 days to an officer senior to the PIO, and a second appeal to the Information Commission within 90 days","a single appeal to the Information Commission within 60 days, whose decision is final"],"answer":2,"explanation":"Section 19 provides a first appeal within 30 days to a senior officer in the same authority and a second appeal within 90 days to the Central or State Information Commission.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-144","question":"Under the Lokpal and Lokayuktas Act, 2013, the Lokpal cannot inquire into an allegation against the Prime Minister that relates to some subjects. Which of these is NOT among them?","options":["Atomic energy","Space","Public order","Award of public contracts"],"answer":3,"explanation":"The excluded subjects are international relations, external and internal security, public order, atomic energy and space. Allegations about contracts are within the Lokpal's reach.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-145","question":"Consider the following statements about the Lokpal's inquiry into an allegation against the Prime Minister: 1. It can begin only if the full bench considers it and at least two-thirds of the members approve. 2. It is held in camera, and if the complaint is dismissed the records are not published. 3. The Lokpal cannot inquire into any allegation against a sitting Prime Minister. Which of the above are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"The Act brings the PM within the Lokpal's jurisdiction, with the safeguards in 1 and 2 and a list of excluded subjects. Statement 3 is the trap.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-146","question":"The first Administrative Reforms Commission (1966), which recommended the institutions of Lokpal and Lokayukta, was initially headed by:","options":["K. Santhanam","L. M. Singhvi","Morarji Desai","Veerappa Moily"],"answer":2,"explanation":"Morarji Desai chaired it until he became Deputy PM in 1967, when K. Hanumanthaiya took over. Santhanam led the anti-corruption committee of 1962–64, and Moily the second ARC.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-147","question":"Under Article 338(9), who must consult the National Commission for Scheduled Castes on all major policy matters affecting Scheduled Castes?","options":["Both the Union and every State Government","Only the Union Government","Only State Governments with a large SC population","Only the Union Government, and only when Parliament so directs"],"answer":0,"explanation":"Article 338(9) binds the Union and every State Government to consult the Commission. Article 338A(9) places the same duty in respect of the Commission for STs.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-148","question":"Consider the following statements about the National Commission for Scheduled Castes: 1. While investigating a complaint, it has all the powers of a civil court trying a suit. 2. It reports to the President, who lays the reports before Parliament with a memorandum on the action taken. 3. Where a report concerns a State, a copy goes to the Governor, who lays it before the State legislature. How many of the above statements are correct?","options":["Only one","Only two","All three","None"],"answer":2,"explanation":"Article 338(6), (7) and (8) provide for all three. The civil court powers cover summoning witnesses, requiring documents and receiving evidence on affidavit.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-149","question":"Match the Article with the body it provides for: A. Article 339 B. Article 340 C. Article 344 D. Article 350B — 1. Commission and Committee of Parliament on official language 2. Commission to investigate the conditions of backward classes 3. Special Officer for linguistic minorities 4. Commission on the administration of Scheduled Areas and welfare of Scheduled Tribes","options":["A-2, B-4, C-1, D-3","A-4, B-2, C-1, D-3","A-4, B-2, C-3, D-1","A-2, B-4, C-3, D-1"],"answer":1,"explanation":"Article 339 led to the Dhebar Commission, Article 340 to the Kalelkar and Mandal Commissions, Article 344 to the Official Language Commission, and Article 350B (7th Amendment) to the Special Officer.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-150","question":"Which two commissions were appointed under Article 340 to investigate the conditions of socially and educationally backward classes?","options":["U. N. Dhebar Commission and Mandal Commission","Kaka Kalelkar Commission and B. G. Kher Commission","Mandal Commission and Sachar Committee","Kaka Kalelkar Commission and Mandal Commission"],"answer":3,"explanation":"Kalelkar (1953) and B. P. Mandal (1979) were Article 340 commissions. Dhebar was under Article 339, Kher was the Official Language Commission, and Sachar was a non-constitutional committee.","difficulty":"hard","source":"UPSC Prelims · State PSCs"},
  {"id":"polity-constitutional-bodies-151","question":"Consider the following statements about Article 344: 1. The President was to constitute an Official Language Commission five years after the Constitution began, and again after ten years. 2. Its recommendations are examined by a Committee of 30 members of Parliament, 15 from each House. 3. The first such Commission was chaired by B. G. Kher. Which of the above are correct?","options":["1 only","1 and 3 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"The Committee has 20 Lok Sabha and 10 Rajya Sabha members, elected by proportional representation, so statement 2 is wrong. The Kher Commission was set up in 1955.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-152","question":"Which of these bodies was NOT created by an executive resolution of the Union Government?","options":["Planning Commission","National Development Council","NITI Aayog","Finance Commission"],"answer":3,"explanation":"The Finance Commission is a constitutional body under Article 280. The other three were set up by Cabinet resolutions in 1950, 1952 and 2015.","difficulty":"moderate","source":"UPSC Prelims · SSC CGL"},
  {"id":"polity-constitutional-bodies-153","question":"The CAG's audit reports on government companies and other public undertakings are examined in Parliament mainly by the:","options":["Committee on Public Undertakings","Estimates Committee","Business Advisory Committee","Committee on Subordinate Legislation"],"answer":0,"explanation":"The CAG's reports on public undertakings go to the COPU, while the appropriation and finance accounts reports go to the Public Accounts Committee. The Estimates Committee does not work on CAG reports.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-154","question":"Consider the following statements about the Election Commission under the Constitution: 1. The Constitution prescribes the qualifications for appointment as an Election Commissioner. 2. The Constitution does not fix the term of office of the Election Commissioners. 3. The Constitution does not bar retiring Election Commissioners from further appointment by the government. Which of the above are correct?","options":["1 and 2 only","1 and 3 only","2 and 3 only","1, 2 and 3"],"answer":2,"explanation":"Article 324 leaves qualifications and tenure to law or rules, and has no clause like Article 148(4) or 319 barring later office. These gaps are often cited as weaknesses.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-155","question":"For which of these offices does the Constitution itself bar further employment under the Government of India or a State after leaving office? 1. Comptroller and Auditor General 2. Chairman of the UPSC 3. Chief Election Commissioner","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"Articles 148(4) and 319(a) impose the bar on the CAG and the UPSC Chairman. No such provision exists for the CEC.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-156","question":"Consider the following statements about a State Finance Commission under Article 243I: 1. It is constituted by the Governor every fifth year. 2. Its recommendations are laid before the State legislature with a memorandum on the action taken. 3. Its recommendations bind the State Government. Which of the above are correct?","options":["1 only","2 and 3 only","1, 2 and 3","1 and 2 only"],"answer":3,"explanation":"Like the central Finance Commission, the SFC is advisory. Its report on panchayat (and, under Article 243Y, municipal) finances is laid before the legislature with an action-taken memorandum.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-157","question":"Consider the following statements about the GST Council: 1. One-half of its total members form the quorum. 2. Its members from the States choose a Vice-Chairperson from among themselves. 3. Union Territories with a legislature, such as Delhi and Puducherry, are represented in it. How many of the above statements are correct?","options":["None","Only one","Only two","All three"],"answer":3,"explanation":"Article 279A provides for the quorum and the Vice-Chairperson, and Article 366(26B) treats a Union Territory with a legislature as a ‘State’ for GST purposes.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-158","question":"In practice, who is appointed Returning Officer for the election of the President of India?","options":["The Secretary-General of the Lok Sabha or of the Rajya Sabha, by rotation","The Chief Election Commissioner himself","The Chief Electoral Officer of Delhi","The Union Home Secretary"],"answer":0,"explanation":"The Election Commission, in consultation with the Union Government, appoints the Secretary-General of one House or the other by turns. The CEC supervises but is not the Returning Officer.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-159","question":"Consider the following statements about the National Human Rights Commission: 1. It cannot inquire into a matter more than one year after the alleged violation. 2. For complaints against the armed forces, it can only seek a report from the Union Government and make recommendations. 3. It can itself punish those it finds guilty of violations. Which of the above are correct?","options":["1 only","2 and 3 only","1 and 2 only","1, 2 and 3"],"answer":2,"explanation":"Sections 36(2) and 19 of the Protection of Human Rights Act support 1 and 2. The NHRC recommends prosecution or compensation; it has no power to punish.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-160","question":"Under the Protection of Human Rights Act, 1993, a Human Rights Court in a district is:","options":["a bench of the State Human Rights Commission sitting in the district","a Court of Session specified by the State Government with the concurrence of the High Court's Chief Justice","a special court set up by the NHRC in each district","a Lok Adalat empowered to try human rights offences"],"answer":1,"explanation":"Section 30 lets the State Government, with the Chief Justice's concurrence, designate a Sessions Court in each district as a Human Rights Court for speedy trial.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-161","question":"Assertion (A): The Attorney General for India is not a member of the Union Council of Ministers. Reason (R): Article 88 gives the Attorney General the right to speak in either House of Parliament, but not to vote.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":1,"explanation":"Both are true. A rests on the AG being a law officer appointed under Article 76, not a minister; the right to speak in Parliament is a separate privilege that does not explain it.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-162","question":"Under Article 317(4), a member of a Public Service Commission is deemed guilty of misbehaviour if he:","options":["becomes interested in a contract made by the Union or a State Government, or shares in its profits otherwise than as an ordinary shareholder of a company","publicly criticises a policy of the Government","is adjudged insolvent","takes up paid employment outside his duties"],"answer":0,"explanation":"Article 317(4) defines this as misbehaviour, which needs a Supreme Court inquiry. Insolvency and outside paid employment are separate grounds under Article 317(3) on which the President removes a member directly.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-163","question":"While the Supreme Court inquires into the alleged misbehaviour of a member of a State Public Service Commission, who may suspend him from office?","options":["The President","The Chief Justice of the High Court","The Governor","The Chief Justice of India"],"answer":2,"explanation":"Under Article 317(2), the Governor may suspend a State PSC member pending the inquiry, though only the President can finally remove him.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-164","question":"Under the Lokpal and Lokayuktas Act, 2013, the Lokpal cannot inquire into a complaint if it is made after what period from the date of the alleged offence?","options":["One year","Three years","Seven years","There is no time limit"],"answer":2,"explanation":"Section 53 sets a limit of seven years. The one-year limit belongs to the National Human Rights Commission.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-165","question":"Which State was the first to set up the institution of Lokayukta, in 1971?","options":["Maharashtra","Odisha","Karnataka","Kerala"],"answer":0,"explanation":"Maharashtra's Lokayukta began work in 1971. Odisha passed its Act in 1970, but the institution there became functional only later.","difficulty":"moderate","source":"UPSC Prelims · State PSCs"},
  {"id":"polity-constitutional-bodies-166","question":"The National Commission to Review the Working of the Constitution, set up in 2000, was chaired by:","options":["Justice R. S. Sarkaria","Justice M. M. Punchhi","Justice A. M. Ahmadi","Justice M. N. Venkatachaliah"],"answer":3,"explanation":"Justice Venkatachaliah headed the commission, which reported in 2002. Sarkaria and Punchhi headed commissions on Centre–State relations.","difficulty":"moderate","source":"UPSC Prelims · State PSCs"},
  {"id":"polity-constitutional-bodies-167","question":"The first Law Commission of independent India (1955) was chaired by the country's first Attorney General. Who was he?","options":["P. B. Gajendragadkar","M. C. Setalvad","K. N. Wanchoo","C. K. Daphtary"],"answer":1,"explanation":"M. C. Setalvad was the first Attorney General and chaired the first post-independence Law Commission. The Law Commission is a non-statutory body set up by executive order.","difficulty":"moderate","source":"UPSC Prelims · State PSCs"},
  {"id":"polity-constitutional-bodies-168","question":"Consider the following statements about the Election Commission under Article 324: 1. The number of Election Commissioners other than the Chief Election Commissioner is fixed by the President from time to time. 2. The President or the Governor must make available to the Commission such staff as it requests for conducting elections. 3. An Election Commissioner can be removed only on the recommendation of the Chief Election Commissioner. How many of the above statements are correct?","options":["Only one","Only two","All three","None of them"],"answer":2,"explanation":"Article 324(2), 324(6) and the proviso to 324(5) support the three statements respectively.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-169","question":"Consider the following statements about Article 329: 1. The validity of a law on the delimitation of constituencies cannot be questioned in any court. 2. An election to Parliament or a State legislature can be called in question only by an election petition. 3. A High Court may, under Article 226, stay an ongoing election process on any ground of illegality. Which of the above is/are correct?","options":["1 and 2 only","1 only","2 and 3 only","1, 2 and 3"],"answer":0,"explanation":"Article 329(a) and (b) give 1 and 2. Since N. P. Ponnuswami (1952), courts do not interfere with the election process midway; grievances go to an election petition afterwards, so 3 is wrong.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-170","question":"In Mohinder Singh Gill v. Chief Election Commissioner (1978), the Supreme Court held that Article 324:","options":["Lets the Commission postpone elections indefinitely whenever it sees a law and order problem","Is a reservoir of power the Commission may use where the law is silent, as in ordering a repoll","Makes every order of the Commission immune from judicial scrutiny, even by election petition","Lets the Commission make election rules that override Acts of Parliament wherever they conflict"],"answer":1,"explanation":"The Court said the Commission's plenary power fills gaps left by law, but it must act fairly and cannot override a statute; its orders remain subject to review through an election petition.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-171","question":"In Sadiq Ali v. Election Commission of India (1971), arising from the Congress split of 1969, the Supreme Court upheld:","options":["The right of Parliament alone to settle disputes between rival factions of a party","The Speaker's power to recognise the larger faction in the Lok Sabha as the real party","The power of the civil courts to decide who owns a party's name and its reserved symbol","The Commission's power under the Symbols Order to decide which rival group is the party"],"answer":3,"explanation":"The Court upheld the Election Symbols (Reservation and Allotment) Order, 1968, and the Commission's use of the test of majority support in deciding the dispute.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-172","question":"In Indian National Congress (I) v. Institute of Social Welfare (2002), the Supreme Court held that the Election Commission, while registering political parties under Section 29A of the Representation of the People Act:","options":["Can deregister any registered party that fails to contest elections for six years","Acts quasi-judicially and cannot deregister a party save in narrow cases like fraud","Can deregister a party whenever its office-bearers are convicted of any offence","Acts only administratively and so can withdraw any registration at its own discretion"],"answer":1,"explanation":"Since the Act gives no power of deregistration, the Commission can cancel registration only in limited cases, such as fraud or a party ceasing to bear allegiance to the Constitution.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-173","question":"In Lily Thomas v. Union of India (2013), the Supreme Court struck down Section 8(4) of the Representation of the People Act. What did that provision do?","options":["It barred every candidate facing a pending criminal case from contesting any election","It allowed persons lodged in jail to contest elections but not to vote in them","It disqualified a convicted sitting legislator only after the Supreme Court upheld the conviction","It spared a sitting legislator immediate disqualification if he appealed within three months"],"answer":3,"explanation":"After Lily Thomas, a sitting MP or MLA convicted of an offence carrying disqualification is disqualified from the date of conviction, like any other candidate.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-174","question":"In Union of India v. Association for Democratic Reforms (2002), the Supreme Court held that voters have a right to know, and directed that candidates disclose:","options":["Their party's sources of funds and its audited annual accounts","Their criminal antecedents, assets and liabilities, and education","Their income-tax returns for each of the previous ten years","Their family ties with any sitting legislator or any Union minister"],"answer":1,"explanation":"The Court traced the voter's right to information to Article 19(1)(a); the Election Commission then made affidavits on these matters compulsory with nomination papers.","difficulty":"moderate","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-175","question":"Under Section 151A of the Representation of the People Act, a bye-election to fill a vacancy in the Lok Sabha must ordinarily be held within six months of the vacancy. This does NOT apply when:","options":["The vacancy arose because the member died","The constituency is reserved for Scheduled Castes","The remainder of the member's term is less than one year","The Rajya Sabha is in session at the time of the vacancy"],"answer":2,"explanation":"No bye-election is needed if less than a year of the term remains, or if the Commission, in consultation with the Centre, certifies that holding it within six months is difficult.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-176","question":"Consider the following statements: 1. Election campaigning by public meetings must stop 48 hours before the close of polling in a constituency. 2. The Representation of the People Act bars publishing exit poll results during the period notified by the Election Commission. 3. These restrictions are contained in the Model Code of Conduct and have no statutory basis. Which of the above is/are correct?","options":["1 and 2 only","1 only","2 and 3 only","1, 2 and 3"],"answer":0,"explanation":"Sections 126 and 126A of the Representation of the People Act give 1 and 2. The Model Code itself has no statutory backing, but these two rules are in the Act, so 3 is wrong.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-177","question":"In Subramanian Swamy v. Election Commission of India (2013), the Supreme Court held that:","options":["Electronic voting machines must be scrapped and replaced by paper ballots","A ‘None of the Above’ option must be added to every electronic voting machine","Electoral bonds are unconstitutional and must stop being issued from the next poll","A paper trail (VVPAT) is essential to free and fair polls and must be phased in"],"answer":3,"explanation":"The Court directed the Commission to introduce VVPATs in phases. NOTA came from the PUCL judgment of 2013, and electoral bonds were struck down in 2024.","difficulty":"moderate","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-178","question":"The orders of the Delimitation Commission, once published in the Gazette, are laid before the Lok Sabha and the State Assemblies concerned. What can these Houses do with them?","options":["Reject them by a two-thirds majority vote","Nothing; they cannot modify the orders","Refer them to the Supreme Court for review","Modify them by a simple majority vote"],"answer":1,"explanation":"Delimitation orders have the force of law and cannot be modified by the Houses or questioned in any court (Article 329(a)).","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-179","question":"Consider the following statements: 1. The administrative expenses of the Union Public Service Commission are charged on the Consolidated Fund of India. 2. The administrative expenses of the office of the CAG, including the salaries of its staff, are charged on the Consolidated Fund of India. 3. The expenses of a State Public Service Commission are charged on the Consolidated Fund of India. Which of the above is/are correct?","options":["1 and 2 only","1 only","2 and 3 only","1, 2 and 3"],"answer":0,"explanation":"Article 322 charges UPSC expenses on the Consolidated Fund of India and Article 148(6) does the same for the CAG's office. A State PSC's expenses are charged on the Consolidated Fund of the State.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-180","question":"Consider the following statements about the CAG: 1. The conditions of service of persons in the Indian Audit and Accounts Department are prescribed by the President after consulting the CAG. 2. The CAG's salary is determined by Parliament by law. 3. After leaving office, the CAG may be appointed Governor of a State. Which of the above is/are correct?","options":["1 and 2 only","1 only","2 and 3 only","1, 2 and 3"],"answer":0,"explanation":"Article 148(5) and 148(3) give 1 and 2. Article 148(4) bars the CAG from any further office under the Government of India or a State, so 3 is wrong.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-181","question":"What was the effect of the separation of accounts from audit in 1976?","options":["The CAG lost its constitutional power to audit the accounts of the States and their companies","The CAG became responsible for drawing up the annual Union Budget with the Finance Ministry","Compiling Union accounts passed from the CAG to ministries under the Controller General of Accounts","Audit of public sector companies was handed over to private chartered accountants alone"],"answer":2,"explanation":"Departmentalisation of Union accounts in 1976 left the CAG as auditor only at the Union level; the CAG still compiles accounts for most States.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-182","question":"The CAG submits three audit reports on the Union to the President. Which of the following is NOT one of them?","options":["Audit report on the appropriation accounts","Audit report on the finance accounts of the Union Government","Audit report on the public undertakings","Report on the Budget estimates for the coming year"],"answer":3,"explanation":"The CAG audits money already spent or received; the Budget estimates of the coming year are prepared by the Ministry of Finance, not reported on by the CAG.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-183","question":"How is ‘secret service expenditure’ treated in audit by the CAG?","options":["The CAG audits it fully and reports to Parliament in a closed sitting","The CAG accepts an administrative certificate and cannot call for its details","It is audited by a sitting Supreme Court judge instead of the CAG","It is wholly exempt from audit and is not certified by any authority at all"],"answer":1,"explanation":"This is a known limit on the CAG: the executive certifies that the money was spent under its authority, and the CAG cannot demand particulars.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-184","question":"Consider the following statements about the Fifteenth Finance Commission: 1. It recommended a 41% share for the States in the divisible pool. 2. The fall from 42% reflected the reorganisation of Jammu and Kashmir into Union territories. 3. It used the 2011 Census population in its formula. How many of the above statements are correct?","options":["Only one","Only two","All three","None of them"],"answer":2,"explanation":"All three are correct. Using the 2011 Census worried southern States, so the Commission added a ‘demographic performance’ criterion to reward lower fertility.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-185","question":"In the Fifteenth Finance Commission's formula for sharing taxes among States, which criterion carried the largest weight?","options":["Population (2011)","Area","Income distance","Demographic performance"],"answer":2,"explanation":"Income distance had 45%, population and area 15% each, forest and ecology 10%, demographic performance 12.5% and tax effort 2.5%.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-186","question":"Consider the following statements about the Attorney General for India: 1. He must be qualified to be appointed a judge of the Supreme Court. 2. He enjoys the privileges and immunities available to a Member of Parliament. 3. He can be removed only in the manner of a Supreme Court judge. Which of the above is/are correct?","options":["1 and 2 only","1 only","2 and 3 only","1, 2 and 3"],"answer":0,"explanation":"Article 76(1) and 105(4) give 1 and 2. The Attorney General holds office during the President's pleasure (Article 76(4)), so 3 is wrong.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-187","question":"Under Article 338(10), as it stands after the 102nd Amendment, references to the Scheduled Castes in Article 338 are also construed to include which group, for the purposes of the National Commission for Scheduled Castes?","options":["Denotified tribes","Religious minorities","Socially and educationally backward classes","The Anglo-Indian community"],"answer":3,"explanation":"The 102nd Amendment removed backward classes from Article 338(10) (they went to the new NCBC under Article 338B), but the Anglo-Indian community remains within the NCSC's remit.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-188","question":"Before it became a constitutional body in 2018, the National Commission for Backward Classes existed as a statutory body set up in 1993 following:","options":["The Sarkaria Commission's report","The Supreme Court's direction in Indra Sawhney (1992)","The 73rd Amendment's provision for backward class reservation","The recommendation of the Kaka Kalelkar Commission"],"answer":1,"explanation":"Indra Sawhney directed a permanent body to examine inclusion and exclusion in the backward class lists; the National Commission for Backward Classes Act, 1993 followed.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-189","question":"Regarding complaints of human rights violations by members of the armed forces, the National Human Rights Commission may:","options":["Inquire fully, summon officers and order compensation","Refer the matter directly to a Human Rights Court for trial","Only seek a report from the Central Government and make recommendations","Take no action at all, since the armed forces are fully outside its scope"],"answer":2,"explanation":"Section 19 of the Protection of Human Rights Act, 1993 limits the NHRC to seeking a report and recommending action; the Government then informs it of the action taken.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-190","question":"The National Human Rights Commission was set up in conformity with which international standards for national human rights institutions?","options":["The Vienna Declaration","The Helsinki Accords","The Geneva Conventions","The Paris Principles"],"answer":3,"explanation":"The Paris Principles (1991, endorsed by the UN General Assembly in 1993) set standards of independence and pluralism for such institutions.","difficulty":"moderate","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-191","question":"Under Section 24 of the RTI Act, 2005, intelligence and security organisations listed in its Second Schedule are exempt from the Act, EXCEPT for information about:","options":["Allegations of corruption and of human rights violations","Their annual budget and their sanctioned staff strength","Their recruitment rules and their promotion policies","Any matter on which a court of law has already passed a final order"],"answer":0,"explanation":"Even exempt organisations must provide information on corruption and human rights allegations, the latter only with the approval of the Information Commission.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-192","question":"Under the RTI Act, 2005, if the information sought concerns the life or liberty of a person, it must be provided within:","options":["48 hours","30 days","7 days","24 hours"],"answer":0,"explanation":"Ordinarily the limit is 30 days, but information concerning life or liberty must be given within 48 hours of the request.","difficulty":"moderate","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-193","question":"In Central Public Information Officer, Supreme Court v. Subhash Chandra Agarwal (2019), a Constitution Bench held that:","options":["Judges' declarations of assets can never be disclosed under the RTI Act","The CJI's office is a public authority under the RTI Act, subject to exemptions","The Supreme Court as an institution lies wholly outside the RTI Act","Collegium deliberations must be disclosed in full to anyone who asks"],"answer":1,"explanation":"The Court held that transparency does not undermine judicial independence, while personal information and confidential matters remain protected case by case.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-194","question":"In Thalappalam Service Co-operative Bank v. State of Kerala (2013), the Supreme Court held that a co-operative society is a ‘public authority’ under the RTI Act:","options":["Only if it has more than one thousand registered members","Always, since it is registered and regulated under a State law","Only if the government owns, controls or substantially finances it","Never, since every co-operative society is a private body"],"answer":2,"explanation":"Mere registration or regulation by the State is not enough; the test is ownership, control or substantial financing by the appropriate government.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-195","question":"The first commission appointed under Article 339(1) to report on the administration of Scheduled Areas and the welfare of Scheduled Tribes was headed by:","options":["B. P. Mandal","B. G. Kher","Kaka Kalelkar","U. N. Dhebar"],"answer":3,"explanation":"The Dhebar Commission (1960–61) was set up under Article 339. Kalelkar and Mandal headed backward class commissions under Article 340, and Kher the Official Language Commission under Article 344.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-196","question":"Section 63 of the Lokpal and Lokayuktas Act, 2013 required every State to:","options":["Place its Lokayukta under the direct supervision of the Lokpal","Appoint only a retired Supreme Court judge as its Lokayukta","Adopt the Central Act's model of Lokayukta without any change at all","Set up a Lokayukta by its own law within one year, unless it had one"],"answer":3,"explanation":"The Act left the form of the Lokayukta to each State's own law but required one to be established within a year of the Act's commencement.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-197","question":"Under the Lokpal and Lokayuktas Act, 2013, which two wings does the Lokpal have for carrying out preliminary inquiries and prosecutions?","options":["A Vigilance Wing and a Judicial Wing","A Complaints Wing and an Enforcement Wing","An Inquiry Wing and a Prosecution Wing","An Investigation Wing and an Audit Wing"],"answer":2,"explanation":"The Inquiry Wing is headed by a Director of Inquiry and the Prosecution Wing by a Director of Prosecution; the Lokpal may also refer cases to agencies such as the CBI.","difficulty":"moderate","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-198","question":"Which of the following bodies falls within the Lokpal's jurisdiction under the 2013 Act, apart from public servants?","options":["Any private company whose annual turnover exceeds ₹100 crore","Any registered political party that receives donations from the public at large","Any religious trust that has been exempted from paying income tax","Any society or trust getting over ₹10 lakh a year from a foreign source"],"answer":3,"explanation":"Section 14 brings in bodies wholly or partly financed by government and societies or trusts receiving foreign contributions above ₹10 lakh a year.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-199","question":"Under Section 6 of the Delhi Special Police Establishment Act, 1946, the CBI can exercise its powers of investigation in a State:","options":["Freely in every State, since it is an agency of the Union Government","Only after the Governor of the State recommends an investigation","Only with that State's consent, unless a constitutional court directs it","Only for offences committed by employees of the Union Government"],"answer":2,"explanation":"The CBI needs State consent, general or case-specific; several States have withdrawn general consent. The Supreme Court held in 2010 that High Courts and the Supreme Court can still direct a CBI inquiry.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-200","question":"Consider the following statements about the Central Vigilance Commission under the CVC Act, 2003: 1. It exercises superintendence over the CBI's investigation of offences under the Prevention of Corruption Act. 2. While inquiring into a complaint, it has the powers of a civil court. 3. It can itself prosecute and punish corrupt public servants. Which of the above is/are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"Sections 8 and 11 of the Act give 1 and 2. The CVC only advises and recommends; prosecution and punishment lie with the courts and disciplinary authorities.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-201","question":"The Governing Council of NITI Aayog consists of the Prime Minister and:","options":["All Union Cabinet ministers and the Governors of all the States","Chief Ministers of only those States that receive central grants","Finance Ministers of all the States and the Governor of the RBI","Chief Ministers of all States and legislature UTs, and LGs of other UTs"],"answer":3,"explanation":"The Governing Council is NITI Aayog's forum of cooperative federalism; Cabinet ministers attend as special invitees or ex officio members, but Governors are not members.","difficulty":"moderate","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-202","question":"The National Development Council, which approved Five-Year Plans, was set up in 1952:","options":["By a Presidential order issued under Article 282","By an Act of Parliament passed for that very purpose","By an executive resolution of the Union Government","Under Article 263 of the Constitution of India"],"answer":2,"explanation":"Like the Planning Commission (1950), the NDC was neither constitutional nor statutory; it was created by an executive resolution in August 1952.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-203","question":"Consider the following statements about the National Green Tribunal: 1. It was set up under the National Green Tribunal Act, 2010. 2. Its chairperson must be a retired Supreme Court judge or a High Court Chief Justice. 3. Appeals from its orders lie to the High Court. Which of the above is/are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"Statements 1 and 2 are correct. Under Section 22 of the Act, appeals lie directly to the Supreme Court, not the High Court.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-204","question":"Consider the following statements about the Central Administrative Tribunal: 1. It was set up under the Administrative Tribunals Act, 1985, enacted under Article 323A. 2. Its decisions can be challenged before a division bench of the High Court. 3. It hears service disputes of members of the armed forces. Which of the above is/are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"After L. Chandra Kumar (1997), CAT orders go first to a High Court division bench. Armed forces service matters go to the Armed Forces Tribunal, so 3 is wrong.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-205","question":"The Law Commission of India is best described as:","options":["A constitutional body set up under Article 324 of the Constitution","A statutory body set up under the Advocates Act, 1961 for law reform","A permanent body set up under the Law Commission Act, 1955","A non-statutory body set up by a Government order for a fixed term"],"answer":3,"explanation":"Each Law Commission is constituted by an executive order, usually for three years; its reports are advisory. There is no Law Commission Act.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-206","question":"The National Commission for Safai Karamcharis was set up under an Act of 1993. What is its status today?","options":["It was merged into the National Commission for Scheduled Castes","It was abolished in 2014 and its functions given to the Lokpal","Its Act lapsed in 2004, and it continues as a non-statutory body","It became a constitutional body under the 89th Amendment in 2003"],"answer":2,"explanation":"The 1993 Act had a sunset clause and lapsed in 2004; the Commission's tenure has since been extended by government resolutions.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-207","question":"The President makes regulations specifying matters on which the UPSC need not be consulted. Under Article 320(5), these regulations:","options":["Must be approved by a resolution of both Houses before taking effect","Are final and need not be placed before Parliament at any stage","Must first be approved by the UPSC itself before being notified","Must lie before each House for 14 days, and Parliament may modify them"],"answer":3,"explanation":"Article 320(5) subjects such regulations to modification or repeal by Parliament, a check on the executive narrowing the UPSC's role.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-208","question":"Under Article 279A, the Vice-Chairperson of the GST Council is:","options":["The Union Minister of State for Finance, ex officio","Chosen by the State members from among themselves","Appointed by the President on the Prime Minister's advice","The Finance Minister of the largest State by population"],"answer":1,"explanation":"The Union Finance Minister chairs the Council; Article 279A(3) lets the State members choose one of themselves as Vice-Chairperson.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-209","question":"The Standing Committee of the Inter-State Council, set up in 1996 to process matters for the Council, is chaired by the:","options":["Union Finance Minister","Prime Minister","Union Home Minister","Cabinet Secretary"],"answer":2,"explanation":"The Prime Minister chairs the Inter-State Council itself; its Standing Committee is chaired by the Union Home Minister.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-210","question":"Under the Right of Children to Free and Compulsory Education Act, 2009, which body monitors the implementation of the right at the national level?","options":["University Grants Commission of India","National Council of Educational Research and Training","National Human Rights Commission of India","National Commission for Protection of Child Rights"],"answer":3,"explanation":"Section 31 of the RTE Act gives this role to the NCPCR, set up under the Commissions for Protection of Child Rights Act, 2005, and to State commissions.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-211","question":"Consider the following statements about a State Information Commission: 1. Its members are appointed by the Governor. 2. They are appointed on the recommendation of a committee of the Chief Minister, the Leader of the Opposition and a Cabinet Minister nominated by the Chief Minister. 3. It hears appeals against decisions of the Central Information Commission. Which of the above is/are correct?","options":["1 and 2 only","1 only","2 and 3 only","1, 2 and 3"],"answer":0,"explanation":"Section 15 of the RTI Act gives 1 and 2. State and Central Commissions work in separate spheres; there is no appeal from one to the other.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-212","question":"Consider the following statements about the National Investigation Agency: 1. It was created by an Act of 2008 after the Mumbai terror attacks. 2. A 2019 amendment allows it to investigate scheduled offences committed outside India against Indian citizens or interests. 3. It is a constitutional body under Article 355. Which of the above is/are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"The NIA is statutory (NIA Act, 2008), and the 2019 amendment extended its reach abroad. Article 355 sets out a Union duty; it creates no agency.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-213","question":"Arrange these bodies in the chronological order of the Acts that set them up or gave them statutory status: 1. National Green Tribunal 2. Central Vigilance Commission 3. National Investigation Agency 4. Lokpal","options":["2, 3, 1, 4","3, 2, 1, 4","2, 1, 3, 4","2, 3, 4, 1"],"answer":0,"explanation":"CVC Act 2003, NIA Act 2008, NGT Act 2010 and Lokpal and Lokayuktas Act 2013.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-214","question":"In a GST Council meeting, 30 States (counting the Union territories with legislatures) are present and all of them vote, and the Union votes in favour of a proposal. The Union's vote counts for one-third of the votes cast and the States together for two-thirds, shared equally. What is the minimum number of States that must vote in favour for the proposal to pass by the required three-fourths?","options":["19","23","15","20"],"answer":0,"explanation":"Each State carries (2/3) ÷ 30 = 2/90 of the vote. The Union's 1/3 plus k × 2/90 must be at least 3/4, so k ≥ 18.75, i.e. 19 States. Without the Union, the States' two-thirds can never reach three-fourths.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-215","question":"Match the body with the authority to which it submits its annual report: A. State Public Service Commission B. National Commission for Scheduled Castes C. State Human Rights Commission D. Central Information Commission — 1. The Governor 2. The President 3. The State Government 4. The Central Government","options":["A-1, B-2, C-3, D-4","A-2, B-1, C-3, D-4","A-1, B-2, C-4, D-3","A-3, B-2, C-1, D-4"],"answer":0,"explanation":"Article 323(2) (SPSC to Governor), Article 338(5)(d) (NCSC to President), Section 28 of the Protection of Human Rights Act (SHRC to State Government) and Section 25 of the RTI Act (CIC to Central Government).","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-216","question":"Consider the following statements about the Election Commission as provided in the Constitution itself: 1. The Constitution does not prescribe qualifications for its members. 2. It does not fix the term of the Election Commissioners. 3. It does not bar retiring Election Commissioners from further appointment by the Government. How many of the above statements are correct?","options":["Only one","Only two","All three","None of them"],"answer":2,"explanation":"All three gaps exist in Article 324 and have long been cited as weaknesses; terms and qualifications are now fixed by statute, not by the Constitution.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-217","question":"Who acts as Vice-Chairman of a Zonal Council set up under the States Reorganisation Act, 1956?","options":["The member States' Chief Ministers, by turns, a year each","The Governor of the largest member State, permanently","The Union Minister of State for Home Affairs, ex officio","The Chief Secretary of the State hosting the meeting"],"answer":0,"explanation":"The Union Home Minister chairs every Zonal Council, and the Chief Ministers of the States in the zone take turns as Vice-Chairman for one year each.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-218","question":"A complaint about a human rights violation is already pending before a State Human Rights Commission. Can the National Human Rights Commission also inquire into it?","options":["No, unless the Governor refers the matter to the NHRC","No; the NHRC cannot inquire into a matter pending before a State Commission","Yes, but only if the State Commission's chairperson consents","Yes; the NHRC can take over any case from a State Commission at will"],"answer":1,"explanation":"Section 36(1) of the Protection of Human Rights Act, 1993 bars the NHRC from inquiring into a matter pending before a State Commission or any other duly constituted commission.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-219","question":"Assertion (A): The recommendations of the National Human Rights Commission are not binding on the Government. Reason (R): Under the Protection of Human Rights Act, 1993, as amended in 2019, the NHRC's Chairperson must be a person who has been Chief Justice of India or a judge of the Supreme Court.","options":["Both A and R are true, and R explains A","Both A and R are true, but R does not explain A","A is true, but R is false","A is false, but R is true"],"answer":1,"explanation":"Both statements are true, but R is unrelated to A: the recommendations are non-binding because the Act gives the Commission only recommendatory powers, whatever the seniority of its Chairperson.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-220","question":"Assertion (A): The Finance Commission is described as a quasi-judicial body. Reason (R): The Finance Commission (Miscellaneous Provisions) Act, 1951 gives it the powers of a civil court, such as summoning witnesses and requiring documents.","options":["Both A and R are true, and R explains A","Both A and R are true, but R does not explain A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Its civil-court powers under the 1951 Act are why the Commission is called quasi-judicial, though its recommendations remain advisory.","difficulty":"moderate","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-221","question":"Which one of the following is a constitutional body?","options":["Lokpal of India","National Human Rights Commission of India","National Commission for Backward Classes","Central Information Commission"],"answer":2,"explanation":"The NCBC became constitutional under Article 338B through the 102nd Amendment (2018). The other three are statutory bodies.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-constitutional-bodies-222","question":"Consider the following statements about the National Commission for Scheduled Castes: 1. It presents reports to the President every year and at other times as it thinks fit. 2. A report on a matter concerning a State is forwarded to the Governor, who has it laid before the State legislature. 3. Its Chairperson is appointed by the Governor of the State with the largest SC population. Which of the above is/are correct?","options":["1 and 2 only","1 only","2 and 3 only","1, 2 and 3"],"answer":0,"explanation":"Article 338(5)(d) and 338(7) give 1 and 2. The Chairperson and members are appointed by the President by warrant (Article 338(3)).","difficulty":"hard","source":"UPSC Prelims"},
];

export default questions;
